 n == \"t\":", "        return \"\\t\"", "    if n == \"r\":", "        return \"\\r\"", "    if n == \"e\":", "        return \"\\e\"", "    if n == \"\\\\\":", "        return \"\\\\\"", "    if n == \"\\{\":", "        return \"\\{\"", "    if n == \"\\}\":", "        return \"\\}\"", "    if n == \"(\":", "        return \"(\"", "    if n == \")\":", "        return \")\"", "    if n == \"\\\"\":", "        return \"\\\"\"", "    if n == \"'\":", "        return \"'\"", "    return NONE", "", "# Форма числового литерала: \"float\" для записи с точкой, иначе \"int\".", "# Используется оператором диапазона, чтобы задать целый/дробный режим.", "func num_form(dict n) -> str:", "    if n[k] == \"un\" AND n[op] == \"-\":", "        return num_form(n[a])", "    if n[k] == \"num\":", "        str raw = n[raw]", "        if raw is NONE:", "            return \"int\"", "        if raw.contains(\".\") OR raw.contains(\"e\") OR raw.contains(\"E\"):", "            return \"float\"", "    return \"int\"", "", "# ---------- лексер ----------", "", "# Сканирует строку или шаблон с позиции i.", "# quoted=TRUE  -> закрывающая кавычка quote", "# quoted=FALSE -> закрывающая скобка \")\"", "# Возвращает {parts, close, err}.", "func scan_parts(str line, flint i, flint lineno, bool quoted, str quote) -> dict:", "    list parts = []", "    list buf = []", "    flint n = len(line)", "", "    while i < n:", "        str c = line[i]", "        if c == \"\\\\\":", "            str nc = char_at(line, i + 1)", "            str v = escape_of(nc)", "            if v is NONE:", "                return {parts: parts, close: i, err: {msg: cat([\"unknown escape '\\\\\", nc, \"'\"]), col: i + 1}}", "            buf.add(v)", "            i += 2", "        elif c == \"\\{\":", "            if len(buf) > 0:", "                parts.add({kind: \"text\", value: buf.join(\"\")})", "                buf = []", "            flint start = i + 1", "            flint depth = 0", "            flint j = start", "            while j < n:", "                str d = line[j]", "                if d == \"\\\"\" OR d == \"'\":", "                    str q = d", "                    j += 1", "                    while j < n:", "                        str e = line[j]", "                        if e == \"\\\\\":", "                            j += 2", "                        elif e == q:", "                            j += 1", "                            break", "                        else:", "                            j += 1", "                elif d == \"\\{\":", "                    depth += 1", "                    j += 1", "                elif d == \"\\}\":", "                    if depth == 0:", "                        break", "                    depth -= 1", "                    j += 1", "                else:", "                    j += 1", "            if j >= n:", "                return {parts: parts, close: i, err: {msg: \"unclosed '\\{'\", col: i + 1}}", "            str inner = line[start..j]", "            if inner.trim() == \"\":", "                return {parts: parts, close: i, err: {msg: \"empty substitution '\\{\\}'\", col: i + 1}}", "            parts.add({kind: \"expr\", src: inner, line: lineno, col: start + 1})", "            i = j + 1", "        elif c == \"\\}\":", "            return {parts: parts, close: i, err: {msg: \"unexpected '\\}': use '\\\\\\}'\", col: i + 1}}", "        elif quoted AND c == quote:", "            if len(buf) > 0:", "                parts.add({kind: \"text\", value: buf.join(\"\")})", "            return {parts: parts, close: i, err: NONE}", "        elif (NOT quoted) AND c == \")\":", "            if len(buf) > 0:", "                parts.add({kind: \"text\", value: buf.join(\"\")})", "            return {parts: parts, close: i, err: NONE}", "        else:", "            buf.add(c)", "            i += 1", "", "    if len(buf) > 0:", "        parts.add({kind: \"text\", value: buf.join(\"\")})", "    if quoted:", "        return {parts: parts, close: i, err: {msg: \"unclosed string\", col: i + 1}}", "    return {parts: parts, close: i, err: {msg: \"unclosed show template: expected ')'\", col: i + 1}}", "", "# Разбирает одну строку (без отступа). Дописывает токены в tokens.", "func scan_line(str line, flint i, flint lineno, list tokens) -> dict:", "    flint n = len(line)", "    while i < n:", "        str c = line[i]", "", "        if c == \" \" OR c == \"\\t\":", "            i += 1", "        elif c == \"#\":", "            return {err: NONE}", "        elif c == \"\\\"\" OR c == \"'\":", "            dict r = scan_parts(line, i + 1, lineno, TRUE, c)", "            if NOT (r[err] is NONE):", "                dict e = r[err]", "                e.add(\"line\", lineno)", "                return {err: e}", "            tokens.add({type: \"string\", parts: r[parts], line: lineno, col: i + 1})", "            i = r[close] + 1", "        elif is_digit(c):", "            flint j = i", "            while j < n AND is_digit(line[j]):", "                j += 1", "            if char_at(line, j) == \".\" AND char_at(line, j + 1) != \".\":", "                j += 1", "                while j < n AND is_digit(line[j]):", "                    j += 1", "            str raw = line[i..j]", "            tokens.add({type: \"number\", value: flint(raw), raw: raw, line: lineno, col: i + 1})", "            i = j", "        elif is_name_start(c):", "            flint j2 = i + 1", "            while j2 < n AND is_name_char(line[j2]):", "                j2 += 1", "            str word = line[i..j2]", "            flint col = i + 1", "", "            if is_template_func(word):", "                flint k = j2", "                while k < n AND (line[k] == \" \" OR line[k] == \"\\t\"):", "                    k += 1", "                if char_at(line, k) == \"(\":", "                    tokens.add({type: \"name\", value: word, line: lineno, col: col})", "                    tokens.add({type: \"op\", value: \"(\", line: lineno, col: k + 1})", "                    dict r2 = scan_parts(line, k + 1, lineno, FALSE, \"\")", "                    if NOT (r2[err] is NONE):", "                        dict e2 = r2[err]", "                        e2.add(\"line\", lineno)", "                        return {err: e2}", "                    # show() — это шаблон: подстановки пишутся в {}.", "                    # show(f(1)) без скобок {}, судя по всему, забыли подстановку:", "                    # первый ')' закрывает вызов, второй — шаблон.", "                    str tpl_raw = line[k + 1..r2[close]]", "                    if tpl_raw.contains(\"(\") AND char_at(line, r2[close] + 1) == \")\":", "                        # scan_parts останавливается на первой ')' — вложенные", "                        # вызовы надо досчитать самим, чтобы подсказка была", "                        # готовым кодом, который можно просто скопировать.", "                        flint dep = 0", "                        flint q = k + 1", "                        while q < len(line):", "                            str ch = line[q]", "                            if ch == \"(\":", "                                dep += 1", "                            elif ch == \")\":", "                                if dep == 0:", "                                    break", "                                dep -= 1", "                            q += 1", "                        str expr_raw = line[k + 1..q]", "                        str expr = expr_raw.trim()", "                        return {err: {line: lineno, col: k + 2, msg: cat([\"wrap the expression in '\\{\\}': \", word, \"(\\{\", expr, \"\\})\"])}}", "                    tokens.add({type: \"template\", parts: r2[parts], line: lineno, col: k + 2})", "                    tokens.add({type: \"op\", value: \")\", line: lineno, col: r2[close] + 1})", "                    i = r2[close] + 1", "                else:", "                    tokens.add({type: \"name\", value: word, line: lineno, col: col})", "                    i = j2", "            elif is_keyword(word):", "                tokens.add({type: \"kw\", value: word, line: lineno, col: col})", "                i = j2", "            else:", "                tokens.add({type: \"name\", value: word, line: lineno, col: col})", "                i = j2", "        else:", "            str three = line[i..i + 3]", "            str two = line[i..i + 2]", "            if is_op3(three):", "                tokens.add({type: \"op\", value: three, line: lineno, col: i + 1})", "                i += 3", "            elif is_op2(two):", "                tokens.add({type: \"op\", value: two, line: lineno, col: i + 1})", "                i += 2", "            elif is_op1(c):", "                tokens.add({type: \"op\", value: c, line: lineno, col: i + 1})", "                i += 1", "            else:", "                return {err: {msg: cat([\"unexpected character '\", c, \"'\"]), line: lineno, col: i + 1}}", "    return {err: NONE}", "", "# Токенизирует весь файл. Возвращает {tokens, err}.", "func lex(str src, str path) -> dict:", "    list tokens = []", "    list indent_stack = [\"\"]", "    flint lineno = 0", "    bool in_block = FALSE", "    list lines = split_lines(src)", "", "    for raw_line in lines:", "        str line = raw_line", "        lineno += 1", "        str trimmed = line.trim()", "", "        bool skip = FALSE", "        if in_block:", "            if trimmed[..3] == \"---\":", "                in_block = FALSE", "            skip = TRUE", "        elif trimmed[..3] == \"---\":", "            in_block = TRUE", "            skip = TRUE", "        elif trimmed == \"\" OR trimmed[..1] == \"#\":", "            skip = TRUE", "        if NOT skip:", "            flint k = 0", "            flint ln = len(line)", "            while k < ln AND (line[k] == \" \" OR line[k] == \"\\t\"):", "                k += 1", "            str indent = line[..k]", "            if indent.contains(\" \") AND indent.contains(\"\\t\"):", "                return {tokens: tokens, err: {msg: \"mixed tabs and spaces in indentation\", line: lineno, col: 1}}", "", "            str top = indent_stack[len(indent_stack) - 1]", "            if indent != top:", "                if indent[..len(top)] == top:", "                    indent_stack.add(indent)", "                    tokens.add({type: \"indent\", line: lineno, col: 1})", "                else:", "                    while len(indent_stack) > 1 AND indent_stack[len(indent_stack) - 1] != indent:", "                        indent_stack.del(len(indent_stack) - 1)", "                        tokens.add({type: \"dedent\", line: lineno, col: 1})", "                    if indent_stack[len(indent_stack) - 1] != indent:", "                        return {tokens: tokens, err: {msg: \"inconsistent indentation\", line: lineno, col: 1}}", "", "            dict r = scan_line(line, len(indent), lineno, tokens)", "            if NOT (r[err] is NONE):", "                return {tokens: tokens, err: r[err]}", "            tokens.add({type: \"newline\", line: lineno, col: len(line) + 1})", "", "    while len(indent_stack) > 1:", "        indent_stack.del(len(indent_stack) - 1)", "        tokens.add({type: \"dedent\", line: lineno, col: 1})", "    tokens.add({type: \"eof\", line: lineno, col: 1})", "    return {tokens: tokens, err: NONE}", "", "# ---------- отладка: --tokens ----------", "", "func describe_tok(dict t) -> str:", "    list p = []", "    p.add(t[type])", "    p.add(\" \")", "    p.add(str(t[line]))", "    p.add(\":\")", "    p.add(str(t[col]))", "    if t.contains(\"value\"):", "        p.add(\" \")", "        p.add(str(t[value]))", "    if t.contains(\"raw\"):", "        p.add(\" raw=\")", "        p.add(t[raw])", "    if t.contains(\"parts\"):", "        p.add(\" parts=\")", "        p.add(str(t[parts]))", "    return p.join(\"\")", "", "func dump_tokens(list toks):", "    for t in toks:", "        show({describe_tok(t)})", "", "# ---------- парсер: состояние и токены ----------", "", "func token_at(dict st, flint i) -> dict:", "    list ts = st[toks]", "    if len(ts) == 0:", "        return {type: \"eof\", line: 1, col: 1}", "    if i < 0 OR i >= len(ts):", "        return ts[len(ts) - 1]", "    return ts[i]", "", "func tk(dict st) -> dict:", "    return token_at(st, st[pos])", "", "func advance(dict st) -> dict:", "    dict t = tk(st)", "    st.add(\"pos\", st[pos] + 1)", "    return t", "", "func tok_is(dict t, str ty, str val) -> bool:", "    if t[type] != ty:", "        return FALSE", "    if val == \"\":", "        return TRUE", "    return t[value] == val", "", "func peek_value(dict st) -> str:", "    dict n = token_at(st, st[pos] + 1)", "    if n[type] == \"op\":", "        return n[value]", "    return \"\"", "", "func fail(dict st, dict t, str ecat, str expected, str found):", "    if NOT (st[err] is NONE):", "        return:", "    dict e = {cat: ecat, line: 1, col: 1, expected: expected, found: found, path: st[path]}", "    if len(t) > 0:", "        e.add(\"line\", t[line])", "        e.add(\"col\", t[col])", "    st.add(\"err\", e)", "", "func expect_tok(dict st, str ty, str val, str what) -> dict:", "    dict t = tk(st)", "    if NOT tok_is(t, ty, val):", "        fail(st, t, \"SYNTAX_ERROR\", what, describe_tok(t))", "        return {type: \"eof\", value: \"\", line: 1, col: 1}", "    advance(st)", "    return t", "", "# ---------- парсер: типы и имена ----------", "", "func is_type_keyword(str w) -> bool:", "    if w == \"str\" OR w == \"flint\" OR w == \"bool\":", "        return TRUE", "    if w == \"list\" OR w == \"dict\" OR w == \"froz\":", "        return TRUE", "    return FALSE", "", "func is_base_type(str w) -> bool:", "    return w == \"str\" OR w == \"flint\" OR w == \"bool\"", "", "# Имя типа без параметров: \"list[flint,str]\" -> \"list\".", "func base_type(str t) -> str:", "    flint i = 0", "    while i < len(t):", "        if t[i] == \"[\":", "            return t[..i]", "        i += 1", "    return t", "", "func is_typed_spec(str t) -> bool:", "    return t.contains(\"[\")", "", "# Список аргументов без пробелов: \"dict[str,flint]\" -> [\"str\", \"flint\"].", "func type_args(str t) -> list:", "    list out = []", "    flint i = 0", "    while i < len(t):", "        if t[i] == \"[\":", "            str inner = t[i + 1..len(t) - 1]", "            flint start = 0", "            flint j = 0", "            while j <= len(inner):", "                if j == len(inner) OR inner[j] == \",\":", "                    out.add(inner[start..j])", "                    start = j + 1", "                j += 1", "            break", "        i += 1", "    return out", "", "# str / flint / bool / list[T,...] / froz[T,...] / dict[K,V].", "func parse_type_spec(dict st) -> str:", "    dict t = tk(st)", "    if t[type] != \"kw\":", "        fail(st, t, \"TYPE_ERROR\", \"type name\", describe_tok(t))", "        return \"\"", "    str base = t[value]", "    if NOT is_type_keyword(base) OR base == \"NONE\":", "        fail(st, t, \"TYPE_ERROR\", \"type name\", describe_tok(t))", "        return \"\"", "    advance(st)", "    if is_base_type(base) OR NOT tok_is(tk(st), \"op\", \"[\"):", "        return base", "    expect_tok(st, \"op\", \"[\", \"'['\")", "    if NOT (st[err] is NONE):", "        return \"\"", "    list targs = []", "    while TRUE:", "        dict at = tk(st)", "        if at[type] != \"kw\" OR NOT is_base_type(at[value]):", "            fail(st, at, \"TYPE_ERROR\", \"str, flint or bool\", describe_tok(at))", "            return \"\"", "        str av = at[value]", "        advance(st)", "        targs.add(av)", "        if tok_is(tk(st), \"op\", \",\") OR (base == \"dict\" AND tok_is(tk(st), \"op\", \"|\")):", "            advance(st)", "        else:", "            break", "    expect_tok(st, \"op\", \"]\", \"']'\")", "    if NOT (st[err] is NONE):", "        return \"\"", "    if base == \"dict\":", "        if len(targs) != 2:", "            fail(st, t, \"TYPE_ERROR\", \"dict[key type,value type]\", \"wrong number of type arguments\")", "            return \"\"", "        if targs[0] != \"str\":", "            fail(st, t, \"TYPE_ERROR\", \"str dict key\", targs[0])", "            return \"\"", "    return cat([base, \"[\", targs.join(\",\"), \"]\"])", "", "func is_numeric(str t) -> bool:", "    return t == \"flint\" OR t == \"NONE\" OR t == \"any\"", "", "func assignable(str from, str to) -> bool:", "    return from == \"NONE\" OR from == \"any\" OR from == to", "", "func is_compare(str op) -> bool:", "    return op == \"==\" OR op == \"!=\" OR op == \"<\" OR op == \"<=\" OR op == \">\" OR op == \">=\"", "", "func is_compound(str op) -> bool:", "    if op == \"+=\" OR op == \"-=\" OR op == \"*=\" OR op == \"/=\":", "        return TRUE", "    return op == \"%=\" OR op == \"//=\" OR op == \"**=\"", "", "func is_const_name(str n) -> bool:", "    if len(n) == 0:", "        return FALSE", "    flint i = 0", "    while i < len(n):", "        str c = n[i]", "        if NOT \"ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_\".contains(c):", "            return FALSE", "        i += 1", "    return TRUE", "", "func builtin_arg_ok(str spec, str t) -> bool:", "    if spec == \"any\":", "        return TRUE", "    if t == \"NONE\" OR t == \"any\":", "        return TRUE", "    if t == spec:", "        return TRUE", "    str b = base_type(t)", "    if spec == \"strlistdict\":", "        return b == \"str\" OR b == \"list\" OR b == \"froz\" OR b == \"dict\"", "    if spec == \"listdict\":", "        return b == \"list\" OR b == \"froz\" OR b == \"dict\"", "    return b == spec", "", "func builtin_arg_desc(str spec) -> str:", "    if spec == \"any\":", "        return \"any value\"", "    if spec == \"strlistdict\":", "        return \"str, list, froz, dict\"", "    if spec == \"listdict\":", "        return \"list, froz, dict\"", "    return spec", "", "func builtin_info(str name) -> dict:", "    if name == \"len\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"strlistdict\"}", "    if name == \"type\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"any\"}", "    if name == \"str\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"any\"}", "    if name == \"flint\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"any\"}", "    if name == \"up\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"low\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"title\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"abs\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"round\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"floor\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"ceil\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"sqrt\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"flint\"}", "    if name == \"min\":", "        return {ok: TRUE, variadic: TRUE, min: 1, max: 9, ret: \"flint\", a1: \"flint\"}", "    if name == \"max\":", "        return {ok: TRUE, variadic: TRUE, min: 1, max: 9, ret: \"flint\", a1: \"flint\"}", "    if name == \"sum\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"list\"}", "    if name == \"avg\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"list\"}", "    if name == \"keys\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"dict\"}", "    if name == \"values\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"dict\"}", "    if name == \"upk\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"listdict\"}", "    if name == \"sort\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"list\"}", "    if name == \"reverse\":", "        return {ok: TRUE, n: 1, ret: \"list\", a1: \"list\"}", "    if name == \"clear\":", "        return {ok: TRUE, n: 1, ret: \"NONE\", a1: \"listdict\"}", "    if name == \"map\":", "        return {ok: TRUE, n: 2, ret: \"list\", a1: \"list\", a2: \"func\"}", "    if name == \"filter\":", "        return {ok: TRUE, n: 2, ret: \"list\", a1: \"list\", a2: \"func\"}", "    if name == \"reduce\":", "        return {ok: TRUE, n: 3, ret: \"any\", a1: \"list\", a2: \"func\", a3: \"any\"}", "    if name == \"system\":", "        return {ok: TRUE, n: 1, ret: \"flint\", a1: \"str\"}", "    if name == \"assert\":", "        return {ok: TRUE, n: 2, ret: \"NONE\", a1: \"any\", a2: \"str\"}", "    if name == \"expect\":", "        return {ok: TRUE, n: 1, ret: \"expect\", a1: \"any\"}", "    if name == \"read_file\":", "        return {ok: TRUE, n: 1, ret: \"str\", a1: \"str\"}", "    if name == \"write_file\":", "        return {ok: TRUE, n: 2, ret: \"bool\", a1: \"str\", a2: \"str\"}", "    if name == \"file_exists\":", "        return {ok: TRUE, n: 1, ret: \"bool\", a1: \"str\"}", "    if name == \"args\":", "        return {ok: TRUE, n: 0, ret: \"list\", a1: \"any\"}", "    if name == \"exit\":", "        return {ok: TRUE, n: 1, ret: \"NONE\", a1: \"flint\"}", "    if name == \"time_ms\":", "        return {ok: TRUE, n: 0, ret: \"flint\", a1: \"any\"}", "    if name == \"is_tty\":", "        return {ok: TRUE, n: 0, ret: \"bool\", a1: \"any\"}", "    return {ok: FALSE}", "", "func is_builtin(str name) -> bool:", "    return builtin_info(name)[ok]", "", "func method_info(str base, str name) -> dict:", "    str b = base_type(base)", "    if b == \"str\":", "        if name == \"part\":", "            return {ok: TRUE, min: 0, max: 2, a1: \"str\", a2: \"flint\", rt: \"str_part\", ret: \"list\", nullable: FALSE}", "        if name == \"find\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_find\", ret: \"flint\", nullable: TRUE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"preff\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_preff\", ret: \"bool\", nullable: FALSE}", "        if name == \"suff\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_suff\", ret: \"bool\", nullable: FALSE}", "        if name == \"trim\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"str\", a2: \"any\", rt: \"str_trim\", ret: \"str\", nullable: FALSE}", "        if name == \"triml\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"str\", a2: \"any\", rt: \"str_triml\", ret: \"str\", nullable: FALSE}", "        if name == \"trimr\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"str\", a2: \"any\", rt: \"str_trimr\", ret: \"str\", nullable: FALSE}", "        if name == \"remove\":", "            return {ok: TRUE, min: 1, max: 2, a1: \"str\", a2: \"flint\", rt: \"str_remove\", ret: \"str\", nullable: FALSE}", "        if name == \"replace\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"str\", a2: \"str\", rt: \"str_replace\", ret: \"str\", nullable: FALSE}", "        if name == \"count\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"str_count\", ret: \"flint\", nullable: FALSE}", "    elif b == \"list\" OR b == \"froz\":", "        if b == \"froz\" AND (name == \"add\" OR name == \"del\" OR name == \"remove\" OR name == \"replace\" OR name == \"replace_value\"):", "            return {ok: FALSE}", "        if name == \"add\":", "            return {ok: TRUE, min: 1, max: 2, a1: \"any\", a2: \"any\", rt: \"list_add\", ret: \"NONE\", nullable: FALSE}", "        if name == \"del\":", "            return {ok: TRUE, min: 0, max: 1, a1: \"flint\", a2: \"any\", rt: \"list_del\", ret: \"NONE\", nullable: FALSE}", "        if name == \"remove\":", "            return {ok: TRUE, min: 1, max: 2, a1: \"any\", a2: \"flint\", rt: \"list_remove\", ret: \"bool\", nullable: FALSE}", "        if name == \"replace\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"flint\", a2: \"any\", rt: \"list_replace\", ret: \"NONE\", nullable: FALSE}", "        if name == \"replace_value\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"any\", a2: \"any\", rt: \"list_replace_value\", ret: \"bool\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"count\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_count\", ret: \"flint\", nullable: FALSE}", "        if name == \"index\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"list_index_of\", ret: \"flint\", nullable: TRUE}", "        if name == \"join\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"list_join\", ret: \"str\", nullable: FALSE}", "    elif b == \"dict\":", "        if name == \"add\":", "            return {ok: TRUE, min: 2, max: 2, a1: \"str\", a2: \"any\", rt: \"dict_add\", ret: \"NONE\", nullable: FALSE}", "        if name == \"take\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_take\", ret: \"any\", nullable: TRUE}", "        if name == \"remove\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_remove\", ret: \"bool\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"str\", a2: \"any\", rt: \"dict_contains\", ret: \"bool\", nullable: FALSE}", "        if name == \"merge\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"dict\", a2: \"any\", rt: \"dict_merge\", ret: \"dict\", nullable: FALSE}", "    elif b == \"expect\":", "        if name == \"equals\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"expect_equals\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_true\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_true\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_false\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_false\", ret: \"NONE\", nullable: FALSE}", "        if name == \"is_none\":", "            return {ok: TRUE, min: 0, max: 0, a1: \"any\", a2: \"any\", rt: \"expect_none\", ret: \"NONE\", nullable: FALSE}", "        if name == \"contains\":", "            return {ok: TRUE, min: 1, max: 1, a1: \"any\", a2: \"any\", rt: \"expect_contains\", ret: \"NONE\", nullable: FALSE}", "    return {ok: FALSE}", "", "func is_reserved(str name) -> bool:", "    if is_builtin(name) OR name == \"show\" OR name == \"show_err\" OR name == \"input\" OR name == \"Error\":", "        return TRUE", "    if name == \"error\" OR name == \"ANY_ERROR\":", "        return TRUE", "    # Методы типов — тоже занятые имена: `add`, `take`, `contains`, `text` и т.д.", "    return method_info(\"str\", name)[ok] OR method_info(\"list\", name)[ok] OR method_info(\"dict\", name)[ok] OR method_info(\"expect\", name)[ok] OR name == \"text\"", "", "# Встроенная модель Error: схема известна компилятору, объект создаёт рантайм.", "func error_schema() -> dict:", "    dict fields = {cat: \"str\", msg: \"str\", file: \"str\", line: \"flint\", col: \"flint\"}", "    dict consts = {}", "    consts.add(\"cat\", TRUE)", "    consts.add(\"msg\", TRUE)", "    consts.add(\"file\", TRUE)", "    consts.add(\"line\", TRUE)", "    consts.add(\"col\", TRUE)", "    dict meth = {}", "    meth.add(\"text\", {params: [], ret: \"str\", ret_nullable: FALSE, line: 1, col: 1})", "    return {name: \"Error\", model_fields: {}, field_types: fields, consts: consts, init_fields: {}, params: [], param_types: {}, methods: meth, method_order: [\"text\"], ctor: NONE, order: [], field_order: []}", "", "# Категории, которые рантайм может положить в error.cat.", "func is_error_category(str c) -> bool:", "    if c == \"ANY_ERROR\" OR c == \"ARGCOUNT_ERROR\" OR c == \"ASSERT_ERROR\":", "        return TRUE", "    if c == \"CONST_ERROR\" OR c == \"EXPECT_ERROR\" OR c == \"FILE_ERROR\":", "        return TRUE", "    if c == \"NAME_ERROR\" OR c == \"RUNTIME_ERROR\" OR c == \"TYPE_ERROR\":", "        return TRUE", "    if c == \"TYPE_MISMATCH_ERROR\" OR c == \"VALUE_ERROR\":", "        return TRUE", "    if c == \"PANIC_ERROR\":", "        return TRUE", "    return FALSE", "", "func is_scalar_type(str t) -> bool:", "    return t == \"str\" OR t == \"flint\" OR t == \"bool\"", "", "func is_model_type(dict st, str t) -> bool:", "    dict ms = st[models]", "    return ms.contains(t)", "", "func model_schema(dict st, str t) -> dict:", "    dict ms = st[models]", "    return ms.take(t)", "", "func check_field_name(dict st, dict tok, str nm):", "    if is_reserved(nm):", "        fail(st, tok, \"NAME_ERROR\", \"free field name\", cat([\"reserved '\", nm, \"'\"]))", "        return:", "", "# Регистрирует экземплярное поле в схеме. new=FALSE — поле уже было.", "func add_model_field(dict st, dict m, dict tok, str nm, str fty, bool computed):", "    dict mf = m[model_fields]", "    dict ft = m[field_types]", "    dict cs = m[consts]", "    dict initf = m[init_fields]", "    dict methods = m[methods]", "    if mf.contains(nm) OR ft.contains(nm) OR methods.contains(nm):", "        fail(st, tok, \"REDECLARE_ERROR\", \"unique field/method name\", cat([\"name '\", nm, \"' is already declared\"]))", "        return:", "    ft.add(nm, fty)", "    list fo = m[field_order]", "    fo.add(nm)", "    if is_const_name(nm):", "        cs.add(nm, TRUE)", "    if computed AND NOT is_const_name(nm):", "        initf.add(nm, TRUE)", "", "func parse_type_name(dict st) -> str:", "    dict t = tk(st)", "    if t[type] == \"name\" AND is_model_type(st, t[value]):", "        advance(st)", "        return t[value]", "    if tok_is(t, \"kw\", \"NONE\"):", "        advance(st)", "        return \"NONE\"", "    return parse_type_spec(st)", "", "# Обычная строка без интерполяции: для ключей dict и сообщения panic.", "func plain_string_of(dict st, dict t) -> str:", "    list parts = t[parts]", "    list buf = []", "    for p0 in parts:", "        dict p = p0", "        if p[kind] != \"text\":", "            fail(st, t, \"TYPE_ERROR\", \"plain string\", \"interpolated string\")", "            return \"\"", "        buf.add(p[value])", "    return buf.join(\"\")", "", "# Соответствует ли литерал параметризованному типу.", "func literal_ok(dict st, dict e, str spec) -> bool:", "    str base = base_type(spec)", "    list targs = type_args(spec)", "    if base == \"list\" OR base == \"froz\":", "        if e[k] != \"list\":", "            return FALSE", "        list its = e[items]", "        for it0 in its:", "            dict it = it0", "            bool ok = FALSE", "            for a0 in targs:", "                str want = a0", "                if it[t] == want:", "                    ok = TRUE", "            if NOT ok:", "                return FALSE", "        return TRUE", "    if base == \"dict\":", "        if e[k] != \"dict\":", "            return FALSE", "        list prs = e[pairs]", "        for pd0 in prs:", "            dict pd = pd0", "            dict pv = pd[value]", "            if pv[t] != targs[1]:", "                return FALSE", "        return TRUE", "    return FALSE", "", "# В новой модели условием может быть только bool (и NONE как ложь).", "func check_condition(dict st, dict e, dict tok):", "    str et = base_type(e[t])", "    if et != \"bool\" AND et != \"NONE\" AND et != \"any\":", "        fail(st, tok, \"TYPE_ERROR\", \"bool condition (TRUE, FALSE or NONE)\", e[t])", "", "# Prelude объявляет функции для проверки типов до разбора пользовательского кода.", "func add_prelude_func(dict st, str name, str lua, list ptypes, str ret):", "    list params = []", "    for pt0 in ptypes:", "        str pt = pt0", "        params.add({name: \"arg\", type: pt, line: 1, col: 1})", "    dict info = {params: params, ret: ret, ret_nullable: FALSE, inferring: FALSE}", "    dict funcs = st[funcs]", "    funcs.add(name, info)", "    dict fnames = st[fnames]", "    fnames.add(name, lua)", "", "func add_prelude(dict st):", "    add_prelude_func(st, \"prelude_cat\", \"prelude_f_1\", [\"str\"], \"str\")", "    add_prelude_func(st, \"path_join\", \"prelude_f_2\", [\"str\", \"str\"], \"str\")", "    add_prelude_func(st, \"now_ms\", \"prelude_f_3\", [], \"flint\")", "    add_prelude_func(st, \"parse_args\", \"prelude_f_4\", [], \"dict\")", "    add_prelude_func(st, \"parse_csv\", \"prelude_f_5\", [\"str\"], \"list\")", "    add_prelude_func(st, \"parse_json\", \"prelude_f_6\", [\"str\"], \"dict\")", "", "func mangle_var(dict st, str name) -> str:", "    st.add(\"vcounter\", st[vcounter] + 1)", "    str lua = cat([\"v_\", str(st[vcounter])])", "    dict names = st[names]", "    names.add(name, lua)", "    return lua", "", "func mangle_func(dict st, str name) -> str:", "    st.add(\"fcounter\", st[fcounter] + 1)", "    str lua = cat([\"f_\", str(st[fcounter])])", "    dict fnames = st[fnames]", "    fnames.add(name, lua)", "    return lua", "", "func e_nullable(dict e) -> bool:", "    if e.contains(\"nullable\"):", "        return e[nullable]", "    return FALSE", "", "# ---------- парсер: выражения ----------", "", "func shift_token_pos(dict t, flint dl, flint dc) -> bool:", "    if NOT t.contains(\"line\"):", "        return TRUE", "    flint old = t[line]", "    t.add(\"line\", old + dl)", "    if old == 1:", "        t.add(\"col\", t[col] + dc)", "    if t.contains(\"parts\"):", "        list ps = t[parts]", "        flint pi = 0", "        while pi < len(ps):", "            shift_token_pos(ps[pi], dl, dc)", "            pi += 1", "    return TRUE", "", "func template_state(dict st, dict p) -> dict:", "    dict lx = lex(p[src], st[path])", "    list ts = lx[tokens]", "    dict e0 = NONE", "    if NOT (lx[err] is NONE):", "        dict le = lx[err]", "        flint eline = p[line] + le[line] - 1", "        flint ecol = le[col]", "        if le[line] == 1:", "            ecol = p[col] + le[col] - 1", "        e0 = {cat: \"SYNTAX_ERROR\", line: eline, col: ecol, msg: le[msg], path: st[path]}", "    flint i = 0", "    while i < len(ts):", "        dict t2 = ts[i]", "        shift_token_pos(t2, p[line] - 1, p[col] - 1)", "        i += 1", "    return {toks: ts, pos: 0, path: st[path], vars: st[vars], nullable: st[nullable], maybe_unset: st[maybe_unset], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], for_names: st[for_names], funcs: st[funcs], in_func: st[in_func], func_ret: st[func_ret], func_returns: st[func_returns], block_depth: st[block_depth], loop_depth: st[loop_depth], cond_depth: st[cond_depth], err: e0, names: st[names], fnames: st[fnames], vcounter: st[vcounter], fcounter: st[fcounter], models: st[models], model_ctx: st[model_ctx]}", "", "func parse_expr(dict st, flint min_bp) -> dict:", "    if NOT (st[err] is NONE):", "        return {}", "    dict t = tk(st)", "    str ty = t[type]", "    dict e = {}", "    dict ptok = NONE", "    str pfn = \"\"", "", "    if ty == \"number\":", "        advance(st)", "        e = {k: \"num\", value: t[value], raw: t[raw], t: \"flint\", line: t[line], col: t[col]}", "    elif ty == \"string\":", "        advance(st)", "        ptok = t", "    elif ty == \"kw\" AND t[value] == \"TRUE\":", "        advance(st)", "        e = {k: \"bool\", value: TRUE, t: \"bool\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"FALSE\":", "        advance(st)", "        e = {k: \"bool\", value: FALSE, t: \"bool\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"NONE\":", "        advance(st)", "        e = {k: \"none\", t: \"NONE\", line: t[line], col: t[col]}", "    elif ty == \"kw\" AND t[value] == \"self\":", "        dict mctx = st[model_ctx]", "        if mctx is NONE:", "            fail(st, t, \"SCOPE_ERROR\", \"'self' inside a model\", \"'self' outside a model\")", "            return {}", "        advance(st)", "        if tok_is(tk(st), \"op\", \"(\"):", "            advance(st)", "            list snames = []", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict snt = expect_tok(st, \"name\", \"\", \"parameter name in self(...)\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    snames.add(snt)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "            if NOT (st[err] is NONE):", "                return {}", "            e = {k: \"self_init\", names: snames, t: \"NONE\", line: t[line], col: t[col]}", "        else:", "            e = {k: \"var\", name: \"self\", lua: \"self\", t: mctx[model_name], line: t[line], col: t[col]}", "    elif ty == \"name\" AND is_model_type(st, t[value]) AND peek_value(st) == \"(\":", "        str cmn = t[value]", "        dict cms = model_schema(st, cmn)", "        dict ccons = cms[ctor]", "        if ccons is NONE:", "            fail(st, t, \"NAME_ERROR\", cat([\"declared construct of '\", cmn, \"'\"]), \"model without construct\")", "            return {}", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        list cmargs = []", "        if NOT tok_is(tk(st), \"op\", \")\"):", "            while TRUE:", "                dict cma = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                cmargs.add(cma)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        list cmparams = ccons[params]", "        if len(cmargs) != len(cmparams):", "            fail(st, t, \"ARGCOUNT_ERROR\", cat([str(len(cmparams)), \" argument(s) to '\", cmn, \"'\"]), cat([str(len(cmargs)), \" argument(s)\"]))", "            return {}", "        list cmpt = []", "        flint cmi = 0", "        while cmi < len(cmargs):", "            dict cma2 = cmargs[cmi]", "            dict cmp = cmparams[cmi]", "            cmpt.add(cmp[type])", "            if NOT assignable(cma2[t], cmp[type]):", "                fail(st, {line: cma2[line], col: cma2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(cmi + 1), \" of '\", cmn, \"' to be \", cmp[type]]), cma2[t])", "                return {}", "            cmi += 1", "        e = {k: \"model_new\", mname: cmn, args: cmargs, ptypes: cmpt, t: cmn, line: t[line], col: t[col]}", "    elif (ty == \"kw\" OR ty == \"name\") AND is_builtin(t[value]) AND peek_value(st) == \"(\":", "        str bn = t[value]", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        list bargs = []", "        if bn == \"map\" OR bn == \"filter\" OR bn == \"reduce\":", "            dict hcoll = parse_expr(st, 0)", "            if NOT (st[err] is NONE):", "                return {}", "            bargs.add(hcoll)", "            expect_tok(st, \"op\", \",\", \"','\")", "            if NOT (st[err] is NONE):", "                return {}", "            dict hft = expect_tok(st, \"name\", \"\", \"function name\")", "            if NOT (st[err] is NONE):", "                return {}", "            str hfn = hft[value]", "            dict hfuncs = st[funcs]", "            if NOT hfuncs.contains(hfn):", "                fail(st, hft, \"NAME_ERROR\", \"declared function\", cat([\"undeclared function '\", hfn, \"'\"]))", "                return {}", "            dict hfi = hfuncs.take(hfn)", "            flint hwant = 1", "            if bn == \"reduce\":", "                hwant = 2", "            if len(hfi[params]) != hwant:", "                fail(st, hft, \"ARGCOUNT_ERROR\", cat([str(hwant), \" parameter(s) in '\", hfn, \"'\"]), cat([str(len(hfi[params])), \" parameter(s)\"]))", "                return {}", "            dict hnames = st[fnames]", "            bargs.add({k: \"func_ref\", name: hfn, lua: hnames.take(hfn), t: \"func\", line: hft[line], col: hft[col]})", "            if bn == \"reduce\":", "                expect_tok(st, \"op\", \",\", \"','\")", "                if NOT (st[err] is NONE):", "                    return {}", "                dict hstart = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                bargs.add(hstart)", "            expect_tok(st, \"op\", \")\", \"')'\")", "        else:", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict ba1 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    bargs.add(ba1)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        dict bi = builtin_info(bn)", "        bool bvari = FALSE", "        if bi.contains(\"variadic\"):", "            bvari = bi[variadic]", "        if bvari:", "            if len(bargs) < bi[min] OR len(bargs) > bi[max]:", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(bi[min]), \"..\", str(bi[max]), \" argument(s) to '\", bn, \"'\"]), cat([str(len(bargs)), \" argument(s)\"]))", "                return {}", "        else:", "            flint np = bi[n]", "            if len(bargs) != np:", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(np), \" argument(s) to '\", bn, \"'\"]), cat([str(len(bargs)), \" argument(s)\"]))", "                return {}", "        flint bai = 0", "        while bai < len(bargs):", "            dict ba2 = bargs[bai]", "            if bvari:", "                if len(bargs) == 1 AND (base_type(ba2[t]) == \"list\" OR ba2[t] == \"any\" OR ba2[t] == \"NONE\"):", "                    bai += 1", "                else:", "                    if NOT builtin_arg_ok(bi[a1], ba2[t]):", "                        fail(st, {line: ba2[line], col: ba2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(bai + 1), \" of '\", bn, \"' to be flint\"]), ba2[t])", "                        return {}", "                    bai += 1", "            else:", "                str bspec = bi[a1]", "                if bai == 1:", "                    bspec = bi[a2]", "                elif bai == 2:", "                    bspec = bi[a3]", "                if NOT builtin_arg_ok(bspec, ba2[t]):", "                    fail(st, {line: ba2[line], col: ba2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(bai + 1), \" of '\", bn, \"' to be \", builtin_arg_desc(bspec)]), ba2[t])", "                    return {}", "                bai += 1", "        if bn == \"str\" AND len(bargs) == 1:", "            dict barg0 = bargs[0]", "            if is_model_type(st, barg0[t]):", "                fail(st, barg0, \"TYPE_ERROR\", \"a field or method inside str(...), not a model instance\", barg0[t])", "                return {}", "        e = {k: \"builtin\", name: bn, args: bargs, t: bi[ret], line: t[line], col: t[col]}", "    elif ty == \"name\" AND is_template_func(t[value]):", "        pfn = t[value]", "        advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        dict tpl = expect_tok(st, \"template\", \"\", \"template\")", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        ptok = tpl", "    elif ty == \"name\":", "        str fn = t[value]", "        if is_model_type(st, fn):", "            fail(st, t, \"TYPE_ERROR\", \"a value, not a model name\", cat([\"model '\", fn, \"'\"]))", "            return {}", "        if peek_value(st) == \"(\":", "            dict funcs = st[funcs]", "            if NOT funcs.contains(fn):", "                fail(st, t, \"NAME_ERROR\", \"declared function\", cat([\"undeclared function '\", fn, \"'\"]))", "                return {}", "            dict fi = funcs.take(fn)", "            if fi[inferring] AND fi[ret] is NONE:", "                fail(st, t, \"TYPE_ERROR\", \"explicit '->' for recursion\", cat([\"'\", fn, \"' is called while its return type is inferred\"]))", "                return {}", "            advance(st)", "            expect_tok(st, \"op\", \"(\", \"'('\")", "            list cargs = []", "            if NOT tok_is(tk(st), \"op\", \")\"):", "                while TRUE:", "                    dict ca1 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    cargs.add(ca1)", "                    if tok_is(tk(st), \"op\", \",\"):", "                        advance(st)", "                    else:", "                        break", "            expect_tok(st, \"op\", \")\", \"')'\")", "            if NOT (st[err] is NONE):", "                return {}", "            list params = fi[params]", "            if len(cargs) != len(params):", "                fail(st, t, \"ARGCOUNT_ERROR\", cat([str(len(params)), \" argument(s) to '\", fn, \"'\"]), cat([str(len(cargs)), \" argument(s)\"]))", "                return {}", "            list ptypes = []", "            flint cai = 0", "            while cai < len(cargs):", "                dict ca2 = cargs[cai]", "                dict pp = params[cai]", "                str pt = pp[type]", "                ptypes.add(pt)", "                if ca2[t] != \"NONE\" AND ca2[t] != \"any\" AND ca2[t] != pt:", "                    fail(st, {line: ca2[line], col: ca2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(cai + 1), \" of '\", fn, \"' to be \", pt]), ca2[t])", "                    return {}", "                cai += 1", "            dict fnames = st[fnames]", "            e = {k: \"call_user\", name: fn, lua: fnames.take(fn), args: cargs, ptypes: ptypes, t: fi[ret], nullable: fi[ret_nullable], line: t[line], col: t[col]}", "        else:", "            str vn = t[value]", "            dict vars = st[vars]", "            bool is_local = vars.contains(vn)", "            dict gv = st[gvars]", "            bool is_global = FALSE", "            bool is_mfield = FALSE", "            dict mctxv = st[model_ctx]", "            if NOT is_local:", "                if gv.contains(vn):", "                    is_global = TRUE", "                elif NOT (mctxv is NONE):", "                    dict ms0 = mctxv[schema]", "                    dict mf0 = ms0[model_fields]", "                    if mf0.contains(vn):", "                        is_mfield = TRUE", "                    else:", "                        fail(st, t, \"NAME_ERROR\", \"declared name\", cat([\"undeclared '\", vn, \"'\"]))", "                        return {}", "                else:", "                    fail(st, t, \"NAME_ERROR\", \"declared name\", cat([\"undeclared '\", vn, \"'\"]))", "                    return {}", "            advance(st)", "            dict names = st[names]", "            bool nl = FALSE", "            str vt = \"\"", "            if is_mfield:", "                dict ms1 = mctxv[schema]", "                dict mf1 = ms1[model_fields]", "                vt = mf1.take(vn)", "                e = {k: \"model_field\", name: vn, mname: mctxv[model_name], t: vt, line: t[line], col: t[col]}", "            else:", "                if is_local:", "                    vt = vars.take(vn)", "                    dict nd = st[nullable]", "                    if nd.contains(vn):", "                        nl = nd.take(vn)", "                    dict mu = st[m