             dict ppd = pp0", "                        if ppd[kind] != \"text\":", "                            fail(st, pkt, \"TYPE_ERROR\", \"plain string pkey\", \"interpolated string\")", "                            return {}", "                        pbuf.add(ppd[value])", "                    pkey = pbuf.join(\"\")", "                else:", "                    fail(st, pkt, \"TYPE_ERROR\", \"dict pkey as bare name or string literal\", describe_tok(pkt))", "                    return {}", "                expect_tok(st, \"op\", \"]\", \"']'\")", "                if NOT (st[err] is NONE):", "                    return {}", "                e = {k: \"dget\", base: e, key: pkey, t: \"any\", nullable: TRUE, line: nt[line], col: nt[col]}", "            else:", "                str bbt = base_type(bt)", "                if bbt != \"str\" AND bbt != \"list\" AND bbt != \"froz\" AND bt != \"NONE\" AND bt != \"any\":", "                    fail(st, nt, \"TYPE_ERROR\", \"str, list, froz or dict receiver of an index\", bt)", "                    return {}", "                dict from = {}", "                bool has_from = FALSE", "                if NOT tok_is(tk(st), \"op\", \"..\"):", "                    from = parse_expr(st, 36)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    has_from = TRUE", "                if tok_is(tk(st), \"op\", \"..\"):", "                    advance(st)", "                    dict to = {}", "                    bool has_to = FALSE", "                    if NOT tok_is(tk(st), \"op\", \"]\"):", "                        to = parse_expr(st, 36)", "                        if NOT (st[err] is NONE):", "                            return {}", "                        has_to = TRUE", "                    dict step = {}", "                    bool has_step = FALSE", "                    if tok_is(tk(st), \"op\", \"..\"):", "                        advance(st)", "                        step = parse_expr(st, 36)", "                        if NOT (st[err] is NONE):", "                            return {}", "                        has_step = TRUE", "                    expect_tok(st, \"op\", \"]\", \"']'\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    list bounds = []", "                    if has_from:", "                        bounds.add(from)", "                    if has_to:", "                        bounds.add(to)", "                    if has_step:", "                        bounds.add(step)", "                    for b0 in bounds:", "                        dict sb = b0", "                        if sb[t] != \"flint\" AND sb[t] != \"NONE\" AND sb[t] != \"any\":", "                            fail(st, {line: sb[line], col: sb[col]}, \"TYPE_ERROR\", \"slice bound to be flint\", sb[t])", "                            return {}", "                    str stype = \"any\"", "                    if bbt == \"list\" OR bbt == \"froz\":", "                        stype = bt", "                    elif bbt == \"str\":", "                        stype = \"str\"", "                    dict node = {k: \"slice\", base: e, t: stype, line: nt[line], col: nt[col]}", "                    if has_from:", "                        node.add(\"from\", from)", "                    else:", "                        node.add(\"from\", NONE)", "                    if has_to:", "                        node.add(\"to\", to)", "                    else:", "                        node.add(\"to\", NONE)", "                    if has_step:", "                        node.add(\"step\", step)", "                    else:", "                        node.add(\"step\", NONE)", "                    e = node", "                else:", "                    expect_tok(st, \"op\", \"]\", \"']'\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    if from[t] != \"flint\" AND from[t] != \"NONE\" AND from[t] != \"any\":", "                        fail(st, {line: from[line], col: from[col]}, \"TYPE_ERROR\", \"index to be flint\", from[t])", "                        return {}", "                    str itype = \"any\"", "                    if bt == \"str\":", "                        itype = \"str\"", "                    e = {k: \"index\", base: e, index: from, t: itype, line: nt[line], col: nt[col]}", "        elif nt[type] == \"op\" AND nt[value] == \".\":", "            advance(st)", "            dict mt = tk(st)", "            str mname = \"\"", "            if mt[type] == \"name\":", "                advance(st)", "                mname = mt[value]", "            else:", "                fail(st, mt, \"SYNTAX_ERROR\", \"field or method name\", describe_tok(mt))", "                return {}", "            str mbt = e[t]", "            if is_model_type(st, mbt):", "                dict ms = model_schema(st, mbt)", "                dict mms = ms[methods]", "                if tok_is(tk(st), \"op\", \"(\"):", "                    if NOT mms.contains(mname):", "                        fail(st, mt, \"NAME_ERROR\", cat([mbt, \" method\"]), cat([\"unknown method '\", mname, \"'\"]))", "                        return {}", "                    dict mm = mms.take(mname)", "                    advance(st)", "                    list margs = []", "                    if NOT tok_is(tk(st), \"op\", \")\"):", "                        while TRUE:", "                            dict ma = parse_expr(st, 0)", "                            if NOT (st[err] is NONE):", "                                return {}", "                            margs.add(ma)", "                            if tok_is(tk(st), \"op\", \",\"):", "                                advance(st)", "                            else:", "                                break", "                    expect_tok(st, \"op\", \")\", \"')'\")", "                    if NOT (st[err] is NONE):", "                        return {}", "                    list mparams = mm[params]", "                    if len(margs) != len(mparams):", "                        fail(st, mt, \"ARGCOUNT_ERROR\", cat([str(len(mparams)), \" argument(s) to '\", mname, \"'\"]), cat([str(len(margs)), \" argument(s)\"]))", "                        return {}", "                    list mpt = []", "                    flint mai = 0", "                    while mai < len(margs):", "                        dict mma = margs[mai]", "                        dict mmp = mparams[mai]", "                        mpt.add(mmp[type])", "                        if NOT assignable(mma[t], mmp[type]):", "                            fail(st, {line: mma[line], col: mma[col]}, \"TYPE_ERROR\", cat([\"argument \", str(mai + 1), \" of '\", mname, \"' to be \", mmp[type]]), mma[t])", "                            return {}", "                        mai += 1", "                    e = {k: \"model_method\", base: e, mname: mbt, name: mname, args: margs, ptypes: mpt, t: mm[ret], nullable: mm[ret_nullable], line: mt[line], col: mt[col]}", "                else:", "                    dict mfs = ms[model_fields]", "                    dict fts = ms[field_types]", "                    if mfs.contains(mname):", "                        e = {k: \"field\", base: e, name: mname, mname: mbt, model_field: TRUE, is_const: TRUE, t: mfs.take(mname), line: mt[line], col: mt[col]}", "                    elif fts.contains(mname):", "                        dict mcs = ms[consts]", "                        bool fconst = mcs.contains(mname)", "                        e = {k: \"field\", base: e, name: mname, mname: mbt, model_field: FALSE, is_const: fconst, t: fts.take(mname), line: mt[line], col: mt[col]}", "                    else:", "                        dict mctxf = st[model_ctx]", "                        bool self_new = FALSE", "                        if NOT (mctxf is NONE):", "                            if mctxf[in