, mt, \"TYPE_ERROR\", cat([\"str, list, froz or dict receiver of '\", mname, \"'\"]), mbt)", "                    return {}", "                flint mn = mi[min]", "                flint mx = mi[max]", "                if len(bmargs) < mn OR len(bmargs) > mx:", "                    str want = str(mn)", "                    if mn != mx:", "                        want = cat([str(mn), \"..\", str(mx)])", "                    fail(st, mt, \"ARGCOUNT_ERROR\", cat([want, \" argument(s) to '\", mname, \"'\"]), cat([str(len(bmargs)), \" argument(s)\"]))", "                    return {}", "                flint ai2 = 0", "                while ai2 < len(bmargs):", "                    dict mma2 = bmargs[ai2]", "                    str mspec = mi[a1]", "                    if ai2 == 1:", "                        mspec = mi[a2]", "                    if mspec != \"any\" AND mma2[t] != \"NONE\" AND mma2[t] != \"any\" AND mma2[t] != mspec:", "                        fail(st, {line: mma2[line], col: mma2[col]}, \"TYPE_ERROR\", cat([\"argument \", str(ai2 + 1), \" of '\", mname, \"' to be \", mspec]), mma2[t])", "                        return {}", "                    ai2 += 1", "                e = {k: \"method\", base: e, name: mname, rt: mi[rt], args: bmargs, a1: mi[a1], a2: mi[a2], t: mi[ret], nullable: mi[nullable], line: mt[line], col: mt[col]}", "        else:", "            more = FALSE", "", "    # инфиксные операторы", "    more = TRUE", "    while more:", "        if NOT (st[err] is NONE):", "            return {}", "        dict it2 = tk(st)", "        str nty = it2[type]", "        if nty == \"op\":", "            str op = it2[value]", "            if is_compare(op):", "                if 30 <= min_bp:", "                    more = FALSE", "                else:", "                    list ops = []", "                    list operands = [e]", "                    bool go = TRUE", "                    while go:", "                        dict ot = tk(st)", "                        if ot[type] == \"op\" AND is_compare(ot[value]):", "                            advance(st)", "                            dict rhs = parse_expr(st, 31)", "                            if NOT (st[err] is NONE):", "                                return {}", "                            ops.add({op: ot[value], line: ot[line], col: ot[col]})", "                            operands.add(rhs)", "                        else:", "                            go = FALSE", "                    flint ci = 0", "                    while ci < len(ops):", "                        dict o = ops[ci]", "                        dict oa = operands[ci]", "                        dict ob = operands[ci + 1]", "                        if o[op] != \"==\" AND o[op] != \"!=\":", "                            str at = oa[t]", "                            str btv = ob[t]", "                            bool ok = (at == btv) AND (at == \"flint\" OR at == \"str\")", "                            if NOT ok AND at != \"NONE\" AND btv != \"NONE\" AND at != \"any\" AND btv != \"any\":", "                                fail(st, o, \"TYPE_ERROR\", cat([\"comparable operands of '\", o[op], \"'\"]), cat([at, \" and \", btv]))", "                                return {}", "                        ci += 1", "                    if len(ops) == 1:", "                        dict o0 = ops[0]", "                        e = {k: \"bin\", op: o0[op], a: operands[0], b: operands[1], t: \"bool\", line: o0[line], col: o0[col]}", "                    else:", "                        e = {k: \"chain\", ops: ops, operands: operands, t: \"bool\", line: e[line], col: e[col]}", "            elif op == \"OR\" OR op == \"AND\":", "                flint obp = 10", "                if op == \"AND\":", "                    obp = 20", "                if obp <= min_bp:", "                    more = FALSE", "                else:", "                    advance(st)", "                    dict orhs = parse_expr(st, obp)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    check_condition(st, e, {line: e[line], col: e[col]})", "                    check_condition(st, orhs, {line: orhs[line], col: orhs[col]})", "                    if NOT (st[err] is NONE):", "                        return {}", "                    e = {k: \"bin\", op: op, a: e, b: orhs, t: \"bool\", line: it2[line], col: it2[col]}", "            elif op == \"..\":", "                if 35 <= min_bp:", "                    more = FALSE", "                else:", "                    advance(st)", "                    dict rto = parse_expr(st, 36)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    if NOT is_numeric(e[t]) OR NOT is_numeric(rto[t]):", "                        fail(st, it2, \"TYPE_ERROR\", \"range bounds to be flint\", cat([e[t], \" and \", rto[t]]))", "                        return {}", "                    if num_form(e) == \"float\" OR num_form(rto) == \"float\":", "                        fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"integer range bound\", \"float\")", "                        return {}", "                    dict rstep = {k: \"num\", value: 1, raw: \"1\", t: \"flint\", line: it2[line], col: it2[col]}", "                    str rkind = \"int\"", "                    bool rhas_step = FALSE", "                    if tok_is(tk(st), \"op\", \"..\"):", "                        advance(st)", "                        rhas_step = TRUE", "                        rstep = parse_expr(st, 36)", "                        if NOT (st[err] is NONE):", "                            return {}", "                        if NOT is_numeric(rstep[t]):", "                            fail(st, {line: rstep[line], col: rstep[col]}, \"TYPE_ERROR\", \"range step to be flint\", rstep[t])", "                            return {}", "                        if num_form(rstep) == \"float\":", "                            rkind = \"float\"", "                    e = {k: \"range\", from: e, to: rto, step: rstep, kind: rkind, has_step: rhas_step, t: \"range\", line: it2[line], col: it2[col]}", "            elif op == \"+\" OR op == \"-\" OR op == \"*\" OR op == \"/\" OR op == \"//\" OR op == \"%\":", "                flint abp = 40", "                if op == \"*\" OR op == \"/\" OR op == \"//\" OR op == \"%\":", "                    abp = 50", "                if abp <= min_bp:", "                    more = FALSE", "                else:", "                    advance(st)", "                    dict arhs = parse_expr(st, abp)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    if op == \"+\" AND (e[t] == \"str\" OR arhs[t] == \"str\"):", "                        fail(st, it2, \"CONCATENATE_NOT_SUPPORT\", \"numeric operands of '+'\", \"str\")", "                        return {}", "                    if NOT (is_numeric(e[t]) AND is_numeric(arhs[t])):", "                        fail(st, it2, \"TYPE_ERROR\", cat([\"operands of '\", op, \"' to be flint\"]), cat([e[t], \" and \", arhs[t]]))", "                        return {}", "                    e = {k: \"bin\", op: op, a: e, b: arhs, t: \"flint\", line: it2[line], col: it2[col]}", "            elif op == \"**\":", "                if 70 <= min_bp:", "                    more = FALSE", "                else:", "                    advance(st)", "                    dict prhs = parse_expr(st, 69)", "                    if NOT (st[err] is NONE):", "                        return {}", "                    if NOT (is_numeric(e[t]) AND is_numeric(prhs[t])):", "                        fail(st, it2, \"TYPE_ERROR\", \"operands of '**' to be flint\", cat([e[t], \" and \", prhs[t]]))", "                        return {}", "                    e = {k: \"bin\", op: \"**\", a: e, b: prhs, t: \"flint\", line: it2[line], col: it2[col]}", "            else:", "                more = FALSE", "        elif nty == \"kw\" AND (it2[value] == \"OR\" OR it2[value] == \"AND\"):", "            str lop = it2[value]", "            flint lbp = 10", "            if lop == \"AND\":", "                lbp = 20", "            if lbp <= min_bp:", "                more = FALSE", "            else:", "                advance(st)", "                dict lrhs = parse_expr(st, lbp)", "                if NOT (st[err] is NONE):", "                    return {}", "                check_condition(st, e, {line: e[line], col: e[col]})", "                check_condition(st, lrhs, {line: lrhs[line], col: lrhs[col]})", "                if NOT (st[err] is NONE):", "                    return {}", "                e = {k: \"bin\", op: lop, a: e, b: lrhs, t: \"bool\", line: it2[line], col: it2[col]}", "        elif nty == \"kw\" AND it2[value] == \"is\":", "            if 30 <= min_bp:", "                more = FALSE", "            else:", "                advance(st)", "                str tn = parse_type_name(st)", "                if NOT (st[err] is NONE):", "                    return {}", "                e = {k: \"is\", a: e, typename: tn, t: \"bool\", line: it2[line], col: it2[col]}", "        elif nty == \"kw\" AND it2[value] == \"in\":", "            if 30 <= min_bp:", "                more = FALSE", "            else:", "                advance(st)", "                dict memrhs = parse_expr(st, 31)", "                if NOT (st[err] is NONE):", "                    return {}", "                str memrt = memrhs[t]", "                if memrt != \"range\" AND base_type(memrt) != \"list\" AND base_type(memrt) != \"dict\" AND memrt != \"str\" AND memrt != \"any\":", "                    fail(st, {line: memrhs[line], col: memrhs[col]}, \"TYPE_ERROR\", \"right operand of 'in' to be range, list, froz, dict or str\", memrt)", "                    return {}", "                e = {k: \"in\", a: e, b: memrhs, t: \"bool\", line: it2[line], col: it2[col]}", "        else:", "            more = FALSE", "", "    return e", "", "# panic(\"CATEGORY\"[, \"message\"]). Категория и сообщение — plain-строки.", "func parse_panic(dict st) -> dict:", "    dict ptok = advance(st)", "    expect_tok(st, \"op\", \"(\", \"'('\")", "    if NOT (st[err] is NONE):", "        return {}", "    dict ct = parse_expr(st, 0)", "    if NOT (st[err] is NONE):", "        return {}", "    if ct[k] != \"str\":", "        fail(st, {line: ct[line], col: ct[col]}, \"TYPE_ERROR\", \"string panic category\", ct[t])", "        return {}", "    str catv = plain_string_of(st, ct)", "    if NOT (st[err] is NONE):", "        return {}", "    if NOT is_error_category(catv):", "        fail(st, {line: ct[line], col: ct[col]}, \"VALUE_ERROR\", \"known error category\", catv)", "        return {}", "    str msg = catv", "    if tok_is(tk(st), \"op\", \",\"):", "        advance(st)", "        dict mt = parse_expr(st, 0)", "        if NOT (st[err] is NONE):", "            return {}", "        if mt[k] != \"str\":", "            fail(st, {line: mt[line], col: mt[col]}, \"TYPE_ERROR\", \"string panic message\", mt[t])", "            return {}", "        msg = plain_string_of(st, mt)", "        if NOT (st[err] is NONE):", "            return {}", "    expect_tok(st, \"op\", \")\", \"')'\")", "    if NOT (st[err] is NONE):", "        return {}", "    return {k: \"panic\", cat: catv, msg: msg, line: ptok[line], col: ptok[col]}", "", "# ---------- парсер: операторы ----------", "", "func stmt_is_decl(dict st) -> bool:", "    dict t = tk(st)", "    dict nx = token_at(st, st[pos] + 1)", "    if t[type] == \"name\" AND is_model_type(st, t[value]):", "        return nx[type] == \"name\"", "    if t[type] != \"kw\":", "        return FALSE", "    str v = t[value]", "    if NOT is_type_keyword(v):", "        return FALSE", "    if nx[type] == \"op\" AND nx[value] == \"(\" AND (v == \"str\" OR v == \"flint\"):", "        return FALSE", "    return TRUE", "", "# Блок типов: `str:`, `flint:` и т.д. Отличается от обычного объявления", "# двоеточием сразу после типа.", "func stmt_is_decl_block(dict st) -> bool:", "    dict t = tk(st)", "    if t[type] != \"kw\":", "        return FALSE", "    if NOT is_type_keyword(t[value]):", "        return FALSE", "    dict nx = token_at(st, st[pos] + 1)", "    return nx[type] == \"op\" AND nx[value] == \":\"", "", "# Куда пишет присваивание: в локальную (или верхнеуровневую) или в глобальную.", "# Зону изменений открывают только функция и цикл. Условие — не зона: если", "# присваивание лежит внутри if/elif/else, оно запрещено даже внутри функции.", "func top_write_forbidden(dict st, str n) -> bool:", "    dict allg = st[gvars]", "    if NOT allg.contains(n):", "        return FALSE", "    if st[cond_depth] > 0:", "        return TRUE", "    return NOT st[in_func] AND st[loop_depth] == 0", "", "func resolve_write(dict st, dict tok, str n) -> dict:", "    if n == \"error\":", "        fail(st, tok, \"CONST_ERROR\", \"variable\", cat([\"handler variable '\", n, \"' is read-only\"]))", "        return {}", "    dict vars = st[vars]", "    dict gv = st[gvars]", "    if vars.contains(n):", "        if is_const_name(n):", "            fail(st, tok, \"CONST_ERROR\", \"variable\", cat([\"constant '\", n, \"'\"]))", "            return {}", "        if top_write_forbidden(st, n):", "            fail(st, tok, \"TOPLEVEL_ERROR\", \"assignment inside a nested block\", cat([\"assignment to top-level variable '\", n, \"'\"]))", "            return {}", "        dict nm = st[names]", "        return {kind: \"local\", type: vars.take(n), lua: nm.take(n)}", "    if gv.contains(n):", "        if is_const_name(n):", "            fail(st, tok, \"CONST_ERROR\", \"variable\", cat([\"constant '\", n, \"'\"]))", "            return {}", "        if top_write_forbidden(st, n):", "            fail(st, tok, \"TOPLEVEL_ERROR\", \"assignment inside a nested block\", cat([\"assignment to top-level variable '\", n, \"'\"]))", "            return {}", "        dict nm2 = st[names]", "        return {kind: \"global\", type: gv.take(n), lua: nm2.take(n)}", "    fail(st, tok, \"NAME_ERROR\", \"declared variable\", cat([\"name '\", n, \"' is not declared\"]))", "    return {}", "", "# Объявление `имя = выражение` с заданным типом. Общее для обычного", "# объявления и для строки внутри блока типов.", "func parse_typed_decl(dict st, str dty, dict dname_tok) -> dict:", "    str dname = dname_tok[value]", "    if is_reserved(dname):", "        fail(st, dname_tok, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", dname, \"'\"]))", "        return {}", "    dict dvars = st[vars]", "    dict dfuncs = st[funcs]", "    if dvars.contains(dname) OR dfuncs.contains(dname):", "        fail(st, dname_tok, \"REDECLARE_ERROR\", \"unique name\", cat([\"name '\", dname, \"' is already declared\"]))", "        return {}", "    if st[in_func]:", "        dict dg = st[gvars]", "        if dg.contains(dname):", "            fail(st, dname_tok, \"REDECLARE_ERROR\", \"local name\", cat([\"global '\", dname, \"' is already declared\"]))", "            return {}", "    dict dctx = st[model_ctx]", "    if NOT (dctx is NONE):", "        dict dms = dctx[schema]", "        dict dft = dms[field_types]", "        dict dmeth = dms[methods]", "        if dft.contains(dname) OR dmeth.contains(dname):", "            fail(st, dname_tok, \"REDECLARE_ERROR\", \"local name\", cat([\"model member '\", dname, \"'\"]))", "            return {}", "    expect_tok(st, \"op\", \"=\", \"'='\")", "    if NOT (st[err] is NONE):", "        return {}", "    dict dexpr = {}", "    if is_model_type(st, dty) AND tok_is(tk(st), \"kw\", \"init\"):", "        dict inittok = advance(st)", "        expect_tok(st, \"op\", \"(\", \"'('\")", "        dict ms = model_schema(st, dty)", "        dict cons = ms[ctor]", "        if cons is NONE:", "            fail(st, inittok, \"NAME_ERROR\", cat([\"declared construct of '\", dty, \"'\"]), \"model without construct\")", "            return {}", "        list iparams = cons[params]", "        dict iparm = {}", "        flint ii = 0", "        while ii < len(iparams):", "            dict ipp = iparams[ii]", "            iparm.add(ipp[name], TRUE)", "            ii += 1", "        list iargs = []", "        dict iseen = {}", "        if NOT tok_is(tk(st), \"op\", \")\"):", "            while TRUE:", "                dict iat = expect_tok(st, \"name\", \"\", \"init argument name\")", "                if NOT (st[err] is NONE):", "                    return {}", "                str ian = iat[value]", "                if iseen.contains(ian):", "                    fail(st, iat, \"REDECLARE_ERROR\", \"unique init argument\", cat([\"duplicate '\", ian, \"'\"]))", "                    return {}", "                iseen.add(ian, TRUE)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                dict iav = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return {}", "                bool iok = FALSE", "                str iwant = \"any\"", "                if iparm.contains(ian):", "                    flint ij = 0", "                    while ij < len(iparams):", "                        dict ipj = iparams[ij]", "                        if ipj[name] == ian:", "                            iwant = ipj[type]", "                            iok = TRUE", "                        ij += 1", "                else:", "                    dict iinit = ms[init_fields]", "                    dict ift = ms[field_types]", "                    dict imf = ms[model_fields]", "                    dict icons = ms[consts]", "                    if iinit.contains(ian):", "                        iwant = ift.take(ian)", "                        iok = TRUE", "                    elif imf.contains(ian) OR icons.contains(ian):", "                        fail(st, iat, \"CONST_ERROR\", \"init argument for a mutable field\", cat([\"read-only '\", ian, \"'\"]))", "                        return {}", "                    elif ift.contains(ian):", "                        fail(st, iat, \"CONST_ERROR\", \"init argument for a computed field\", cat([\"field '\", ian, \"' is set from construct parameters\"]))", "                        return {}", "                    else:", "                        fail(st, iat, \"NAME_ERROR\", cat([\"field or construct parameter of '\", dty, \"'\"]), cat([\"unknown '\", ian, \"'\"]))", "                        return {}", "                if NOT assignable(iav[t], iwant):", "                    fail(st, {line: iav[line], col: iav[col]}, \"TYPE_ERROR\", cat([\"init argument '\", ian, \"': type \", iwant]), iav[t])", "                    return {}", "                iargs.add({name: ian, expr: iav, type: iwant})", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                else:", "                    break", "        expect_tok(st, \"op\", \")\", \"')'\")", "        if NOT (st[err] is NONE):", "            return {}", "        flint mi2 = 0", "        while mi2 < len(iparams):", "            dict ipm = iparams[mi2]", "            str need = ipm[name]", "            if NOT iseen.contains(need):", "                fail(st, inittok, \"ARGCOUNT_ERROR\", cat([\"argument '\", need, \"' in init\"]), \"missing\")", "                return {}", "            mi2 += 1", "        dexpr = {k: \"model_init\", mname: dty, args: iargs, t: dty, line: inittok[line], col: inittok[col]}", "    else:", "        dexpr = parse_expr(st, 0)", "        if NOT (st[err] is NONE):", "            return {}", "        if NOT assignable(dexpr[t], dty):", "            bool litok = FALSE", "            if is_typed_spec(dty) AND dexpr[t] != \"NONE\":", "                litok = literal_ok(st, dexpr, dty)", "            if NOT litok:", "                fail(st, {line: dexpr[line], col: dexpr[col]}, \"TYPE_ERROR\", cat([\"declaration of '\", dname, \"': type \", dty]), dexpr[t])", "                return {}", "    str dlua = mangle_var(st, dname)", "    dvars.add(dname, dty)", "    # Любое объявление вне функции — глобальная («верх файла»).", "    # Переприсвоить её можно только в функции или цикле, не в условии.", "    if NOT st[in_func]:", "        dict dtg = st[gvars]", "        dtg.add(dname, dty)", "    dict dnl = st[nullable]", "    if dexpr[t] == \"NONE\" OR e_nullable(dexpr):", "        dnl.add(dname, TRUE)", "    else:", "        dnl.remove(dname)", "    if st[block_depth] > 0:", "        dict dmu = st[maybe_unset]", "        dmu.add(dname, TRUE)", "    return {k: \"decl\", type: dty, name: dname, lua: dlua, expr: dexpr, line: dname_tok[line], col: dname_tok[col]}", "", "func snapshot_parser(dict st) -> dict:", "    return {vars: st[vars], nullable: st[nullable], maybe_unset: st[maybe_unset], for_names: st[for_names], gvars: st[gvars], gnullable: st[gnullable], gmaybe: st[gmaybe], loop_depth: st[loop_depth], cond_depth: st[cond_depth], try_depth: st[try_depth], try_loop_base: st[try_loop_base], in_func: st[in_func], func_ret: st[func_ret], func_returns: st[func_returns], model_ctx: st[model_ctx]}", "", "func restore_parser(dict st, dict sv):", "    st.add(\"vars\", sv[vars])", "    st.add(\"nullable\", sv[nullable])", "    st.add(\"maybe_unset\", sv[maybe_unset])", "    st.add(\"for_names\", sv[for_names])", "    st.add(\"gvars\", sv[gvars])", "    st.add(\"gnullable\", sv[gnullable])", "    st.add(\"gmaybe\", sv[gmaybe])", "    st.add(\"loop_depth\", sv[loop_depth])", "    st.add(\"cond_depth\", sv[cond_depth])", "    st.add(\"try_depth\", sv[try_depth])", "    st.add(\"try_loop_base\", sv[try_loop_base])", "    st.add(\"in_func\", sv[in_func])", "    st.add(\"func_ret\", sv[func_ret])", "    st.add(\"func_returns\", sv[func_returns])", "    st.add(\"model_ctx\", sv[model_ctx])", "", "# Заголовок модели: поле до construct. Тело не разбирает.", "func parse_model_field_decl(dict st, dict m) -> dict:", "    str mfty = advance(st)[value]", "    dict mfnt = expect_tok(st, \"name\", \"\", \"field name\")", "    if NOT (st[err] is NONE):", "        return {}", "    str mfname = mfnt[value]", "    check_field_name(st, mfnt, mfname)", "    if NOT (st[err] is NONE):", "        return {}", "    dict mf = m[model_fields]", "    dict ft = m[field_types]", "    dict meth = m[methods]", "    if mf.contains(mfname) OR ft.contains(mfname) OR meth.contains(mfname):", "        fail(st, mfnt, \"REDECLARE_ERROR\", \"unique field name\", cat([\"name '\", mfname, \"' is already declared\"]))", "        return {}", "    expect_tok(st, \"op\", \"=\", \"'='\")", "    dict sv = st[model_ctx]", "    st.add(\"model_ctx\", NONE)", "    dict mfexpr = parse_expr(st, 0)", "    st.add(\"model_ctx\", sv)", "    if NOT (st[err] is NONE):", "        return {}", "    if NOT assignable(mfexpr[t], mfty):", "        fail(st, {line: mfexpr[line], col: mfexpr[col]}, \"TYPE_ERROR\", cat([\"field '\", mfname, \"': type \", mfty]), mfexpr[t])", "        return {}", "    mf.add(mfname, mfty)", "    ft.add(mfname, mfty)", "    list mo = m[order]", "    mo.add(mfname)", "    list fo = m[field_order]", "    fo.add(mfname)", "    return {name: mfname, type: mfty, expr: mfexpr, line: mfnt[line], col: mfnt[col]}", "", "# Параметры construct (construct=TRUE) или метода. Скобки уже открыты.", "func parse_model_params(dict st, dict m, bool is_cons) -> list:", "    list out = []", "    if NOT tok_is(tk(st), \"op\", \")\"):", "        while TRUE:", "            dict pty_tok = tk(st)", "            str pty = parse_type_name(st)", "            if NOT (st[err] is NONE):", "                return out", "            if pty == \"NONE\":", "                fail(st, pty_tok, \"TYPE_ERROR\", \"parameter type\", \"NONE\")", "                return out", "            dict pnt = expect_tok(st, \"name\", \"\", \"parameter name\")", "            if NOT (st[err] is NONE):", "                return out", "            str pnm = pnt[value]", "            if is_reserved(pnm) OR is_const_name(pnm):", "                fail(st, pnt, \"NAME_ERROR\", \"free parameter name\", cat([\"reserved '\", pnm, \"'\"]))", "                return out", "            dict mf = m[model_fields]", "            dict ft = m[field_types]", "            dict meth = m[methods]", "            if mf.contains(pnm) OR meth.contains(pnm) OR (NOT is_cons AND ft.contains(pnm)):", "                fail(st, pnt, \"REDECLARE_ERROR\", \"parameter name\", cat([\"model member '\", pnm, \"'\"]))", "                return out", "            flint pi = 0", "            while pi < len(out):", "                dict po = out[pi]", "                if po[name] == pnm:", "                    fail(st, pnt, \"REDECLARE_ERROR\", \"unique parameter name\", cat([\"duplicate '\", pnm, \"'\"]))", "                    return out", "                pi += 1", "            out.add({name: pnm, type: pty, line: pnt[line], col: pnt[col]})", "            if tok_is(tk(st), \"op\", \",\"):", "                advance(st)", "            else:", "                break", "    expect_tok(st, \"op\", \")\", \"')'\")", "    return out", "", "func parse_construct_header(dict st, dict m) -> dict:", "    advance(st)", "    expect_tok(st, \"op\", \"(\", \"'('\")", "    list params = parse_model_params(st, m, TRUE)", "    if NOT (st[err] is NONE):", "        return {}", "    expect_tok(st, \"op\", \":\", \"':'\")", "    if NOT (st[err] is NONE):", "        return {}", "    m.add(\"ctor\", {params: params, body: []})", "    list mparams = m[params]", "    dict mptypes = m[param_types]", "    for p0 in params:", "        dict p = p0", "        mparams.add(p[name])", "        mptypes.add(p[name], p[type])", "    dict mctx = {model_name: m[name], schema: m, in_construct: TRUE, level: st[block_depth] + 1, self_seen: FALSE, self_done: FALSE, param_set: {}}", "    dict ps = mctx[param_set]", "    for p1 in params:", "        dict p1d = p1", "        ps.add(p1d[name], TRUE)", "    return {params: params, mctx: mctx}", "", "func parse_method_header(dict st, dict m) -> dict:", "    advance(st)", "    dict mtok = expect_tok(st, \"name\", \"\", \"method name\")", "    if NOT (st[err] is NONE):", "        return {}", "    str mn = mtok[value]", "    if is_reserved(mn) OR is_const_name(mn):", "        fail(st, mtok, \"NAME_ERROR\", \"free method name\", cat([\"reserved '\", mn, \"'\"]))", "        return {}", "    dict mf = m[model_fields]", "    dict ft = m[field_types]", "    dict meth = m[methods]", "    if ft.contains(mn) OR mf.contains(mn) OR meth.contains(mn):", "        fail(st, mtok, \"REDECLARE_ERROR\", \"unique method name\", cat([\"name '\", mn, \"' is already declared\"]))", "        return {}", "    expect_tok(st, \"op\", \"(\", \"'('\")", "    list params = parse_model_params(st, m, FALSE)", "    if NOT (st[err] is NONE):", "        return {}", "    str mret = \"NONE\"", "    bool mhas = FALSE", "    if tok_is(tk(st), \"op\", \"->\"):", "        advance(st)", "        dict mrt = tk(st)", "        mret = parse_type_name(st)", "        if NOT (st[err] is NONE):", "            return {}", "        if mret == \"NONE\":", "            fail(st, mrt, \"SYNTAX_ERROR\", \"return type (omit '->' for NONE)\", \"NONE\")", "            return {}", "        mhas = TRUE", "    expect_tok(st, \"op\", \":\", \"':'\")", "    if NOT (st[err] is NONE):", "        return {}", "    dict info = {params: params, ret: NONE, ret_nullable: FALSE, inferring: TRUE}", "    if mhas:", "        info.add(\"ret\", mret)", "    meth.add(mn, info)", "    list mo = m[method_order]", "    mo.add(mn)", "    return {name: mn, info: info, params: params, ret: mret, has_ret: mhas, line: mtok[line], col: mtok[col]}", "", "func finish_method(dict st, dict info, list body, str declared, bool has_ret, list rets):", "    bool fall = TRUE", "    if len(body) > 0:", "        dict last = body[len(body) - 1]", "        if last[k] == \"return\":", "            fall = FALSE", "    bool nullable = fall", "    str seen = \"\"", "    flint ri = 0", "    while ri < len(rets):", "        dict rr = rets[ri]", "        if rr[empty] OR rr[type] == \"NONE\" OR e_nullable(rr):", "            nullable = TRUE", "        elif has_ret:", "            if rr[type] != declared AND rr[type] != \"any\":", "                fail(st, rr, \"TYPE_ERROR\", cat([\"return type \", declared]), rr[type])", "                return:", "        else:", "            if seen != \"\" AND seen != rr[type]:", "                fail(st, rr, \"TYPE_ERROR\", \"all returns of a method to have one type\", cat([seen, \" and \", rr[type]]))", "                return:", "            seen = rr[type]", "        ri += 1", "    str final = declared", "    if NOT has_ret:", "        final = seen", "        if final == \"\":", "            final = \"NONE\"", "    info.add(\"ret\", final)", "    info.add(\"ret_nullable\", nullable)", "    info.add(\"inferring\", FALSE)", "    info.add(\"body\", body)", "", "# Разбирает блок. top=TRUE — весь файл до eof; top=FALSE — после ':'.", "# Рекурсивна: тела if/while/for/func разбираются ею же.", "func enter_try_zone(dict st, flint old_base):", "    st.add(\"try_depth\", st[try_depth] + 1)", "    flint base = old_base", "    if st[loop_depth] > base:", "        base = st[loop_depth]", "    st.add(\"try_loop_base\", base)", "", "func leave_try_zone(dict st, flint old_base):", "    st.add(\"try_depth\", st[try_depth] - 1)", "    st.add(\"try_loop_base\", old_base)", "", "func try_crosses_loop(dict st) -> bool:", "    return st[try_depth] > 0 AND st[loop_depth] <= st[try_loop_base]", "", "func add_handler_error(dict st) -> dict:", "    dict old_names = st[names]", "    dict old_vars = st[vars]", "    dict old_null = st[nullable]", "    dict old_maybe = st[maybe_unset]", "    bool had_name = old_names.contains(\"error\")", "    bool had_var = old_vars.contains(\"error\")", "    bool had_null = old_null.contains(\"error\")", "    bool had_maybe = old_maybe.contains(\"error\")", "    str prev_name = \"\"", "    str prev_var = \"\"", "    bool prev_null = FALSE", "    bool prev_maybe = FALSE", "    if had_name:", "        prev_name = old_names.take(\"error\")", "    if had_var:", "        prev_var = old_vars.take(\"error\")", "    if had_null:", "        prev_null = old_null.take(\"error\")", "    if had_maybe:", "        prev_maybe = old_maybe.take(\"error\")", "    old_names.add(\"error\", \"error\")", "    old_vars.add(\"error\", \"Error\")", "    return {name: had_name, var: had_var, null: had_null, maybe: had_maybe, prev_name: prev_name, prev_var: prev_var, prev_null: prev_null, prev_maybe: prev_maybe}", "", "func remove_handler_error(dict st, dict sv):", "    dict cur_names = st[names]", "    dict cur_vars = st[vars]", "    dict cur_null = st[nullable]", "    dict cur_maybe = st[maybe_unset]", "    cur_names.remove(\"error\")", "    cur_vars.remove(\"error\")", "    cur_null.remove(\"error\")", "    cur_maybe.remove(\"error\")", "    if sv[name]:", "        cur_names.add(\"error\", sv[prev_name])", "    if sv[var]:", "        cur_vars.add(\"error\", sv[prev_var])", "    if sv[null]:", "        cur_null.add(\"error\", sv[prev_null])", "    if sv[maybe]:", "        cur_maybe.add(\"error\", sv[prev_maybe])", "", "# Категории одного trigger через запятую делят один обработчик.", "# ANY_ERROR не объединяется с другими и не повторяется.", "func parse_trigger_cats(dict st, dict zcats, bool zhas_any) -> dict:", "    list zcatnames = []", "    list zcattoks = []", "    dict zfirsttok = expect_tok(st, \"name\", \"\", \"error category\")", "    if NOT (st[err] is NONE):", "        return {}", "    zcatnames.add(zfirsttok[value])", "    zcattoks.add(zfirsttok)", "    while tok_is(tk(st), \"op\", \",\"):", "        advance(st)", "        dict znexttok = expect_tok(st, \"name\", \"\", \"error category\")", "        if NOT (st[err] is NONE):", "            return {}", "        zcatnames.add(znexttok[value])", "        zcattoks.add(znexttok)", "    flint zci = 0", "    while zci < len(zcatnames):", "        str zcname = zcatnames[zci]", "        dict zctok = zcattoks[zci]", "        if NOT is_error_category(zcname):", "            fail(st, zctok, \"NAME_ERROR\", \"known error category\", zcname)", "            return {}", "        if zhas_any:", "            fail(st, zctok, \"SYNTAX_ERROR\", \"trigger after ANY_ERROR\", cat([\"'\", zcname, \"'\"]))", "            return {}", "        if zcname == \"ANY_ERROR\":", "            if len(zcatnames) != 1:", "                fail(st, zctok, \"SYNTAX_ERROR\", \"ANY_ERROR in a group of triggers\", zcname)", "                return {}", "        else:", "            if zcats.contains(zcname):", "                fail(st, zctok, \"REDECLARE_ERROR\", \"unique trigger category\", cat([\"'\", zcname, \"'\"]))", "                return {}", "            zcats.add(zcname, TRUE)", "        zci += 1", "    dict hinfo = {cats: zcatnames, cat: zfirsttok[value], any: FALSE}", "    if zfirsttok[value] == \"ANY_ERROR\":", "        hinfo.add(\"any\", TRUE)", "    return hinfo", "", "func parse_block(dict st, bool top) -> list:", "    list stmts = []", "    if NOT top:", "        expect_tok(st, \"newline\", \"\", \"end of line after ':'\")", "        expect_tok(st, \"indent\", \"\", \"indented block\")", "        st.add(\"block_depth\", st[block_depth] + 1)", "    bool going = TRUE", "    while going:", "        dict t = tk(st)", "        if NOT (st[err] is NONE):", "            return stmts", "        bool skip = FALSE", "        if top:", "            if t[type] == \"eof\":", "                going = FALSE", "                skip = TRUE", "            elif t[type] == \"newline\" OR t[type] == \"dedent\":", "                advance(st)", "                skip = TRUE", "            elif t[type] == \"indent\":", "                fail(st, t, \"SYNTAX_ERROR\", \"statement\", \"unexpected indent\")", "                return stmts", "        else:", "            if t[type] == \"dedent\" OR t[type] == \"eof\":", "                going = FALSE", "                skip = TRUE", "            elif t[type] == \"newline\":", "                advance(st)", "                skip = TRUE", "        if going AND NOT skip:", "            dict node = {}", "            bool block_stmt = FALSE", "            bool decl_block = FALSE", "            if stmt_is_decl_block(st):", "                dict dbtok = advance(st)", "                str dbty = dbtok[value]", "                advance(st)", "                expect_tok(st, \"newline\", \"\", \"end of line after ':'\")", "                expect_tok(st, \"indent\", \"\", \"indented block\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                flint dcount = 0", "                bool dbgoing = TRUE", "                while dbgoing:", "                    dict dbt = tk(st)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if dbt[type] == \"dedent\" OR dbt[type] == \"eof\":", "                        dbgoing = FALSE", "                    elif dbt[type] == \"newline\":", "                        advance(st)", "                    else:", "                        dict dbnt = expect_tok(st, \"name\", \"\", \"variable name\")", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        dict dbdecl = parse_typed_decl(st, dbty, dbnt)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        stmts.add(dbdecl)", "                        dcount += 1", "                        dict dbnxt = tk(st)", "                        if dbnxt[type] == \"newline\":", "                            advance(st)", "                        elif dbnxt[type] != \"dedent\":", "                            fail(st, dbnxt, \"SYNTAX_ERROR\", \"end of line\", describe_tok(dbnxt))", "                            return stmts", "                if tk(st)[type] == \"dedent\":", "                    advance(st)", "                if dcount == 0:", "                    fail(st, dbtok, \"SYNTAX_ERROR\", \"declaration inside type block\", \"empty block\")", "                    return stmts", "                decl_block = TRUE", "            elif stmt_is_decl(st):", "                str dty = parse_type_name(st)", "                if NOT (st[err] is NONE):", "                    return stmts", "                dict dname_tok = expect_tok(st, \"name\", \"\", \"variable name\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                node = parse_typed_decl(st, dty, dname_tok)", "                if NOT (st[err] is NONE):", "                    return stmts", "            elif t[type] == \"kw\" AND t[value] == \"panic\":", "                node = parse_panic(st)", "                if NOT (st[err] is NONE):", "                    return stmts", "            elif t[type] == \"kw\" AND t[value] == \"if\":", "                dict iftok = advance(st)", "                list branches = []", "                dict cond = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                check_condition(st, cond, {line: cond[line], col: cond[col]})", "                if NOT (st[err] is NONE):", "                    return stmts", "                expect_tok(st, \"op\", \":\", \"':'\")", "                st.add(\"cond_depth\", st[cond_depth] + 1)", "                list ibody = parse_block(st, FALSE)", "                st.add(\"cond_depth\", st[cond_depth] - 1)", "                branches.add({cond: cond, body: ibody})", "                while tok_is(tk(st), \"kw\", \"elif\"):", "                    advance(st)", "                    dict c2 = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    check_condition(st, c2, {line: c2[line], col: c2[col]})", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"cond_depth\", st[cond_depth] + 1)", "                    list b2 = parse_block(st, FALSE)", "                    st.add(\"cond_depth\", st[cond_depth] - 1)", "                    branches.add({cond: c2, body: b2})", "                node = {k: \"if\", branches: branches, block_stmt: TRUE, line: iftok[line], col: iftok[col]}", "                if tok_is(tk(st), \"kw\", \"else\"):", "                    advance(st)", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"cond_depth\", st[cond_depth] + 1)", "                    list eb = parse_block(st, FALSE)", "                    st.add(\"cond_depth\", st[cond_depth] - 1)", "                    node.add(\"else_body\", eb)", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"while\":", "                dict wtok = advance(st)", "                dict wcond = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                check_condition(st, wcond, {line: wcond[line], col: wcond[col]})", "                if NOT (st[err] is NONE):", "                    return stmts", "                expect_tok(st, \"op\", \":\", \"':'\")", "                st.add(\"loop_depth\", st[loop_depth] + 1)", "                list wbody = parse_block(st, FALSE)", "                st.add(\"loop_depth\", st[loop_depth] - 1)", "                node = {k: \"while\", cond: wcond, body: wbody, block_stmt: TRUE, line: wtok[line], col: wtok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"try\":", "                dict trytok = advance(st)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                flint zbase = st[try_loop_base]", "                enter_try_zone(st, zbase)", "                list try_body = parse_block(st, FALSE)", "                leave_try_zone(st, zbase)", "                if NOT (st[err] is NONE):", "                    return stmts", "                list ztriggers = []", "                dict zany = NONE", "                dict zcats = {}", "                while tok_is(tk(st), \"kw\", \"trigger\"):", "                    dict trtok = advance(st)", "                    dict hinfo = parse_trigger_cats(st, zcats, NOT (zany is NONE))", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    enter_try_zone(st, zbase)", "                    dict hsv = add_handler_error(st)", "                    list hbody = parse_block(st, FALSE)", "                    remove_handler_error(st, hsv)", "                    leave_try_zone(st, zbase)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    dict hnode = {cats: hinfo[cats], cat: hinfo[cat], body: hbody, line: trtok[line], col: trtok[col]}", "                    if hinfo[any]:", "                        zany = hnode", "                    else:", "                        ztriggers.add(hnode)", "                if len(ztriggers) == 0 AND zany is NONE:", "                    fail(st, trytok, \"SYNTAX_ERROR\", \"trigger after try\", \"finally\")", "                    return stmts", "                if NOT tok_is(tk(st), \"kw\", \"finally\"):", "                    fail(st, tk(st), \"SYNTAX_ERROR\", \"'finally:'\", describe_tok(tk(st)))", "                    return stmts", "                advance(st)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                enter_try_zone(st, zbase)", "                list zfinally = parse_block(st, FALSE)", "                leave_try_zone(st, zbase)", "                if NOT (st[err] is NONE):", "                    return stmts", "                node = {k: \"try\", body: try_body, triggers: ztriggers, any: zany, \"finally\": zfinally, block_stmt: TRUE, line: trytok[line], col: trytok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"for\":", "                dict ftok = advance(st)", "                list nts = []", "                dict nt1 = expect_tok(st, \"name\", \"\", \"loop variable\")", "                nts.add(nt1)", "                if tok_is(tk(st), \"op\", \",\"):", "                    advance(st)", "                    dict nt2 = expect_tok(st, \"name\", \"\", \"loop variable\")", "                    nts.add(nt2)", "                if tok_is(tk(st), \"kw\", \"in\"):", "                    advance(st)", "                    dict coll = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    list ftypes = []", "                    str cty = base_type(coll[t])", "                    if cty == \"list\":", "                        if len(nts) != 1:", "                            fail(st, nts[1], \"TYPE_ERROR\", \"one loop variable for a list\", \"two variables\")", "                            return stmts", "                        ftypes.add(\"any\")", "                    elif cty == \"froz\":", "                        if len(nts) != 1:", "                            fail(st, nts[1], \"TYPE_ERROR\", \"one loop variable for a froz\", \"two variables\")", "                            return stmts", "                        ftypes.add(\"any\")", "                    elif cty == \"dict\":", "                        if len(nts) != 2:", "                            fail(st, nts[0], \"TYPE_ERROR\", \"two loop variables for a dict (key, value)\", \"one variable\")", "                            return stmts", "                        ftypes.add(\"str\")", "                        ftypes.add(\"any\")", "                    elif cty == \"any\":", "                        if len(nts) == 1:", "                            ftypes.add(\"any\")", "                        else:", "                            ftypes.add(\"str\")", "                            ftypes.add(\"any\")", "                    else:", "                        fail(st, ftok, \"TYPE_ERROR\", \"list or dict after 'in'\", cty)", "                        return stmts", "                    list fnames_k = []", "                    list fnames_l = []", "                    flint ni = 0", "                    while ni < len(nts):", "                        dict ntx = nts[ni]", "                        str nm = ntx[value]", "                        if is_const_name(nm):", "                            fail(st, ntx, \"CONST_ERROR\", \"variable\", cat([\"constant '\", nm, \"'\"]))", "                            return stmts", "                        if is_reserved(nm):", "                            fail(st, ntx, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", nm, \"'\"]))", "                            return stmts", "                        dict fvars = st[vars]", "                        dict ffor = st[for_names]", "                        dict fgv = st[gvars]", "                        if fvars.contains(nm) OR ffor.contains(nm) OR fgv.contains(nm):", "                            fail(st, ntx, \"REDECLARE_ERROR\", \"unique loop variable\", cat([\"name '\", nm, \"' is already declared\"]))", "                            return stmts", "                        fvars.add(nm, ftypes[ni])", "                        ffor.add(nm, TRUE)", "                        fnames_k.add(nm)", "                        fnames_l.add(mangle_var(st, nm))", "                        ni += 1", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"loop_depth\", st[loop_depth] + 1)", "                    list fibody = parse_block(st, FALSE)", "                    st.add(\"loop_depth\", st[loop_depth] - 1)", "                    flint rj = 0", "                    while rj < len(fnames_k):", "                        dict fvars2 = st[vars]", "                        fvars2.remove(fnames_k[rj])", "                        rj += 1", "                    node = {k: \"for_in\", names: fnames_k, lnames: fnames_l, coll: coll, body: fibody, block_stmt: TRUE, line: ftok[line], col: ftok[col]}", "                    block_stmt = TRUE", "                else:", "                    if len(nts) != 1:", "                        fail(st, nts[1], \"SYNTAX_ERROR\", \"one loop variable for a numeric range\", \"two variables\")", "                        return stmts", "                    dict rnt = nts[0]", "                    str rname = rnt[value]", "                    if is_const_name(rname):", "                        fail(st, rnt, \"CONST_ERROR\", \"variable\", cat([\"constant '\", rname, \"'\"]))", "                        return stmts", "                    if is_reserved(rname):", "                        fail(st, rnt, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", rname, \"'\"]))", "                        return stmts", "                    dict rvars = st[vars]", "                    dict rfor = st[for_names]", "                    dict rgv = st[gvars]", "                    if rvars.contains(rname) OR rfor.contains(rname) OR rgv.contains(rname):", "                        fail(st, rnt, \"REDECLARE_ERROR\", \"unique loop variable\", cat([\"name '\", rname, \"' is already declared\"]))", "                        return stmts", "                    rvars.add(rname, \"flint\")", "                    rfor.add(rname, TRUE)", "                    str rlua = mangle_var(st, rname)", "                    dict first = parse_expr(st, 0)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    dict ftnode = {k: \"for\", name: rname, lua: rlua, line: ftok[line], col: ftok[col]}", "                    if first[k] == \"range\":", "                        ftnode.add(\"form\", \"range\")", "                        ftnode.add(\"from\", first[from])", "                        ftnode.add(\"to\", first[to])", "                        if first[has_step]:", "                            ftnode.add(\"step\", first[step])", "                    elif is_numeric(first[t]):", "                        ftnode.add(\"form\", \"upto\")", "                        ftnode.add(\"to\", first)", "                    else:", "                        fail(st, first, \"TYPE_ERROR\", \"loop bound to be flint or range\", first[t])", "                        return stmts", "                    expect_tok(st, \"op\", \":\", \"':'\")", "                    st.add(\"loop_depth\", st[loop_depth] + 1)", "                    list rbody = parse_block(st, FALSE)", "                    st.add(\"loop_depth\", st[loop_depth] - 1)", "                    dict rvars2 = st[vars]", "                    rvars2.remove(rname)", "                    ftnode.add(\"body\", rbody)", "                    ftnode.add(\"block_stmt\", TRUE)", "                    node = ftnode", "                    block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"func\":", "                dict funtok = advance(st)", "                if st[in_func] OR st[block_depth] > 0:", "                    fail(st, funtok, \"SYNTAX_ERROR\", \"function at top level\", \"nested function\")", "                    return stmts", "                dict fntok = expect_tok(st, \"name\", \"\", \"function name\")", "                str fn_name = fntok[value]", "                if is_reserved(fn_name):", "                    fail(st, fntok, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", fn_name, \"'\"]))", "                    return stmts", "                if is_const_name(fn_name):", "                    fail(st, fntok, \"CONST_ERROR\", \"function name\", cat([\"constant '\", fn_name, \"'\"]))", "                    return stmts", "                dict gvars = st[vars]", "                dict gfuncs = st[funcs]", "                if gfuncs.contains(fn_name) OR gvars.contains(fn_name):", "                    fail(st, fntok, \"REDECLARE_ERROR\", \"unique name\", cat([\"name '\", fn_name, \"' is already declared\"]))", "                    return stmts", "                expect_tok(st, \"op\", \"(\", \"'('\")", "                list params = []", "                if NOT tok_is(tk(st), \"op\", \")\"):", "                    while TRUE:", "                        dict pty_tok = tk(st)", "                        str pty = parse_type_name(st)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        if pty == \"NONE\":", "                            fail(st, pty_tok, \"TYPE_ERROR\", \"parameter type\", \"NONE\")", "                            return stmts", "                        dict pn = expect_tok(st, \"name\", \"\", \"parameter name\")", "                        str pnm = pn[value]", "                        if is_reserved(pnm):", "                            fail(st, pn, \"NAME_ERROR\", \"free name\", cat([\"reserved '\", pnm, \"'\"]))", "                            return stmts", "                        dict pgv = st[vars]", "                        if pgv.contains(pnm):", "                            fail(st, pn, \"REDECLARE_ERROR\", \"parameter name\", cat([\"global '\", pnm, \"' is already declared\"]))", "                            return stmts", "                        flint di = 0", "                        while di < len(params):", "                            dict pp0 = params[di]", "                            if pp0[name] == pnm:", "                                fail(st, pn, \"REDECLARE_ERROR\", \"unique parameter name\", cat([\"duplicate '\", pnm, \"'\"]))", "                                return stmts", "                            di += 1", "                        params.add({name: pnm, type: pty, line: pn[line], col: pn[col]})", "                        if tok_is(tk(st), \"op\", \",\"):", "                            advance(st)", "                        else:", "                            break", "                expect_tok(st, \"op\", \")\", \"')'\")", "                str fret = \"NONE\"", "                bool fhas_ret = FALSE", "                if tok_is(tk(st), \"op\", \"->\"):", "                    advance(st)", "                    dict rtok = tk(st)", "                    fret = parse_type_name(st)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if fret == \"NONE\":", "                        fail(st, rtok, \"SYNTAX_ERROR\", \"return type (omit '->' for NONE)\", \"NONE\")", "                        return stmts", "                    fhas_ret = TRUE", "                expect_tok(st, \"op\", \":\", \"':'\")", "                dict fninfo = {params: params, ret: NONE, ret_nullable: FALSE, inferring: TRUE}", "                if fhas_ret:", "                    fninfo.add(\"ret\", fret)", "                gfuncs.add(fn_name, fninfo)", "                str flua = mangle_func(st, fn_name)", "                dict sv_vars = st[vars]", "                dict sv_nullable = st[nullable]", "                dict sv_maybe = st[maybe_unset]", "                dict sv_for = st[for_names]", "                dict sv_gvars = st[gvars]", "                dict sv_gnullable = st[gnullable]", "                dict sv_gmaybe = st[gmaybe]", "                flint sv_loop = st[loop_depth]", "                bool sv_in = st[in_func]", "                str sv_ret = st[func_ret]", "                list sv_returns = st[func_returns]", "                st.add(\"gvars\", st[vars])", "                st.add(\"gnullable\", st[nullable])", "                st.add(\"gmaybe\", st[maybe_unset])", "                st.add(\"vars\", {})", "                st.add(\"nullable\", {})", "                st.add(\"maybe_unset\", {})", "                st.add(\"for_names\", {})", "                st.add(\"loop_depth\", 0)", "                st.add(\"in_func\", TRUE)", "                st.add(\"func_ret\", fret)", "                st.add(\"func_returns\", [])", "                flint pj = 0", "                while pj < len(params):", "                    dict pj_p = params[pj]", "                    pj_p.add(\"lua\", mangle_var(st, pj_p[name]))", "                    dict nv = st[vars]", "                    nv.add(pj_p[name], pj_p[type])", "                    pj += 1", "                list fnbody = parse_block(st, FALSE)", "                list frets = st[func_returns]", "                st.add(\"vars\", sv_vars)", "                st.add(\"nullable\", sv_nullable)", "                st.add(\"maybe_unset\", sv_maybe)", "                st.add(\"for_names\", sv_for)", "                st.add(\"gvars\", sv_gvars)", "                st.add(\"gnullable\", sv_gnullable)", "                st.add(\"gmaybe\", sv_gmaybe)", "                st.add(\"loop_depth\", sv_loop)", "                st.add(\"in_func\", sv_in)", "                st.add(\"func_ret\", sv_ret)", "                st.add(\"func_returns\", sv_returns)", "                bool fallthrough = TRUE", "                if len(fnbody) > 0:", "                    dict last_stmt = fnbody[len(fnbody) - 1]", "                    if last_stmt[k] == \"return\":", "                        fallthrough = FALSE", "                bool fnullable = fallthrough", "                str seen = \"\"", "                flint ri = 0", "                while ri < len(frets):", "                    dict rr = frets[ri]", "                    if rr[empty] OR rr[type] == \"NONE\" OR e_nullable(rr):", "                        fnullable = TRUE", "                    elif fhas_ret:", "                        if rr[type] != fret AND rr[type] != \"any\":", "                            fail(st, rr, \"TYPE_ERROR\", cat([\"return type \", fret]), rr[type])", "                            return stmts", "                    else:", "                        if seen != \"\" AND seen != rr[type]:", "                            fail(st, rr, \"TYPE_ERROR\", cat([\"all returns of '\", fn_name, \"' to have one type\"]), cat([seen, \" and \", rr[type]]))", "                            return stmts", "                        seen = rr[type]", "                    ri += 1", "                str final_ret = fret", "                if NOT fhas_ret:", "                    final_ret = seen", "                    if final_ret == \"\":", "                        final_ret = \"NONE\"", "                fninfo.add(\"ret\", final_ret)", "                fninfo.add(\"ret_nullable\", fnullable)", "                fninfo.add(\"inferring\", FALSE)", "                node = {k: \"func\", name: fn_name, lua: flua, params: params, ret: final_ret, body: fnbody, block_stmt: TRUE, line: funtok[line], col: funtok[col]}", "                block_stmt = TRUE", "            elif t[type] == \"kw\" AND t[value] == \"model\":", "                dict mtok = advance(st)", "                if st[in_func] OR st[block_depth] > 0:", "                    fail(st, mtok, \"SCOPE_ERROR\", \"model at top level\", \"nested model\")", "                    return stmts", "                dict mnt = expect_tok(st, \"name\", \"\", \"model name\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                str mname = mnt[value]", "                if is_reserved(mname) OR is_const_name(mname):", "                    fail(st, mnt, \"NAME_ERROR\", \"free model name\", cat([\"reserved '\", mname, \"'\"]))", "                    return stmts", "                dict mall = st[models]", "                dict mgv = st[vars]", "                dict mfnc = st[funcs]", "                if mall.contains(mname) OR mgv.contains(mname) OR mfnc.contains(mname):", "                    fail(st, mnt, \"REDECLARE_ERROR\", \"unique model name\", cat([\"name '\", mname, \"' is already declared\"]))", "                    return stmts", "                dict mschema = {name: mname, model_fields: {}, field_types: {}, consts: {}, init_fields: {}, params: [], param_types: {}, methods: {}, method_order: [], ctor: NONE, order: [], field_order: []}", "                mall.add(mname, mschema)", "                expect_tok(st, \"op\", \":\", \"':'\")", "                expect_tok(st, \"newline\", \"\", \"end of line after ':'\")", "                expect_tok(st, \"indent\", \"\", \"indented block\")", "                if NOT (st[err] is NONE):", "                    return stmts", "                list mfield_nodes = []", "                bool mseen_construct = FALSE", "                bool mseen_method = FALSE", "                bool mgoing = TRUE", "                while mgoing:", "                    dict mbt = tk(st)", "                    if NOT (st[err] is NONE):", "                        return stmts", "                    if mbt[type] == \"dedent\" OR mbt[type] == \"eof\":", "                        mgoing = FALSE", "                    elif mbt[type] == \"newline\":", "                        advance(st)", "                    elif mbt[type] == \"kw\" AND mbt[value] == \"construct\":", "                        if mseen_construct:", "                            fail(st, mbt, \"REDECLARE_ERROR\", \"one construct per model\", \"second construct\")", "                            return stmts", "                        if mseen_method:", "                            fail(st, mbt, \"SYNTAX_ERROR\", \"construct before methods\", \"construct after method\")", "                            return stmts", "                        dict mch = parse_construct_header(st, mschema)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        list mparams = mch[params]", "                        dict mctx = mch[mctx]", "                        dict sv = snapshot_parser(st)", "                        st.add(\"gvars\", st[vars])", "                        st.add(\"gnullable\", st[nullable])", "                        st.add(\"gmaybe\", st[maybe_unset])", "                        st.add(\"vars\", {})", "                        st.add(\"nullable\", {})", "                        st.add(\"maybe_unset\", {})", "                        st.add(\"for_names\", {})", "                        st.add(\"loop_depth\", 0)", "                        st.add(\"in_func\", TRUE)", "                        st.add(\"func_ret\", \"NONE\")", "                        st.add(\"func_returns\", [])", "                        st.add(\"model_ctx\", mctx)", "                        for p0 in mparams:", "                            dict p = p0", "                            p.add(\"lua\", mangle_var(st, p[name]))", "                            dict pv = st[vars]", "                            pv.add(p[name], p[type])", "                        list mbody = parse_block(st, FALSE)", "                        restore_parser(st, sv)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        if NOT mctx[self_seen]:", "                            fail(st, mtok, \"SYNTAX_ERROR\", \"self(...) as the first statement of construct\", \"missing self(...)\")", "                            return stmts", "                        dict mcons = mschema[ctor]", "                        mcons.add(\"body\", mbody)", "                        mseen_construct = TRUE", "                    elif mbt[type] == \"kw\" AND mbt[value] == \"method\":", "                        if NOT mseen_construct:", "                            fail(st, mbt, \"SYNTAX_ERROR\", \"construct before methods\", \"method before construct\")", "                            return stmts", "                        dict mmh = parse_method_header(st, mschema)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        dict mctx2 = {model_name: mname, schema: mschema, in_construct: FALSE, level: 0, self_seen: TRUE, self_done: TRUE, param_set: {}}", "                        dict sv2 = snapshot_parser(st)", "                        st.add(\"gvars\", st[vars])", "                        st.add(\"gnullable\", st[nullable])", "                        st.add(\"gmaybe\", st[maybe_unset])", "                        st.add(\"vars\", {})", "                        st.add(\"nullable\", {})", "                        st.add(\"maybe_unset\", {})", "                        st.add(\"for_names\", {})", "                        st.add(\"loop_depth\", 0)", "                        st.add(\"in_func\", TRUE)", "                        st.add(\"func_ret\", mmh[ret])", "                        st.add(\"func_returns\", [])", "                        st.add(\"model_ctx\", mctx2)", "                        list mparams2 = mmh[params]", "                        for p3 in mparams2:", "                            dict p3d = p3", "                            p3d.add(\"lua\", mangle_var(st, p3d[name]))", "                            dict pv2 = st[vars]", "                            pv2.add(p3d[name], p3d[type])", "                        list mbody2 = parse_block(st, FALSE)", "                        list mrets = st[func_returns]", "                        restore_parser(st, sv2)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        finish_method(st, mmh[info], mbody2, mmh[ret], mmh[has_ret], mrets)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        mseen_method = TRUE", "                    elif mbt[type] == \"kw\" AND is_scalar_type(mbt[value]):", "                        if mseen_construct OR mseen_method:", "                            fail(st, mbt, \"SYNTAX_ERROR\", \"model fields before construct\", \"field after construct\")", "                            return stmts", "                        dict mfnode = parse_model_field_decl(st, mschema)", "                  