, "                else:", "                    anl.remove(aname)", "                node = {k: \"assign\", name: aname, lua: aw[lua], expr: aexpr, type: avt, line: atok[line], col: atok[col]}", "            elif t[type] == \"name\" AND NOT is_template_func(t[value]) AND is_compound(peek_value(st)):", "                dict ctok = advance(st)", "                str cname = ctok[value]", "                dict cw = resolve_write(st, ctok, cname)", "                if NOT (st[err] is NONE):", "                    return stmts", "                dict cop_tok = advance(st)", "                str cop_full = cop_tok[value]", "                str cop = cop_full[..len(cop_full) - 1]", "                dict cexpr = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                str cvt = cw[type]", "                if cvt != \"flint\" OR NOT is_numeric(cexpr[t]):", "                    fail(st, cop_tok, \"TYPE_ERROR\", cat([\"numeric operands of '\", cop_full, \"'\"]), cexpr[t])", "                    return stmts", "                bool cmaybe = FALSE", "                if cw[kind] == \"global\":", "                    dict cgnl = st[gnullable]", "                    dict cgmu = st[gmaybe]", "                    if cgnl.contains(cname):", "                        cmaybe = TRUE", "                    if cgmu.contains(cname):", "                        cmaybe = TRUE", "                    cgnl.remove(cname)", "                else:", "                    dict cnl = st[nullable]", "                    dict cmu = st[maybe_unset]", "                    if cnl.contains(cname):", "                        cmaybe = TRUE", "                    if cmu.contains(cname):", "                        cmaybe = TRUE", "                    cnl.remove(cname)", "                node = {k: \"compound\", name: cname, lua: cw[lua], op: cop, expr: cexpr, nullable: cmaybe, line: ctok[line], col: ctok[col]}", "            else:", "                dict e = parse_expr(st, 0)", "                if NOT (st[err] is NONE):", "                    return stmts", "                if e[k] == \"self_init\":", "                    dict sctx = st[model_ctx]", "                    if sctx is NONE OR NOT sctx[in_construct]:", "                        fail(st, e, \"SCOPE_ERROR\", \"self(...) in construct\", \"self(...) outside construct\")", "                        return stmts", "                    if st[block_depth] != sctx[level] OR len(stmts) != 0:", "                        fail(st, e, \"SYNTAX_ERROR\", \"self(...) as the first statement of construct\", \"nested or later self(...)\")", "                        return stmts", "                    if sctx[self_seen]:", "                        fail(st, e, \"REDECLARE_ERROR\", \"one self(...) per construct\", \"second self(...)\")", "                        return stmts", "                    list sargs = e[names]", "                    dict ssch = sctx[schema]", "                    dict scons = ssch[ctor]", "                    list sps = []", "                    if NOT (scons is NONE):", "                        sps = scons[params]", "                    flint slast = -1", "                    list sfields = []", "                    flint si = 0", "                    while si < len(sargs):", "                        dict sat = sargs[si]", "                        str san = sat[value]", "                        flint sfound = -1", "                        flint sj = 0", "                        while sj < len(sps):", "                            dict ssp = sps[sj]", "                            if ssp[name] == san:", "                                sfound = sj", "                            sj += 1", "                        if sfound < 0:", "                            fail(st, sat, \"NAME_ERROR\", \"construct parameter in self(...)\", cat([\"unknown '\", san, \"'\"]))", "                            return stmts", "                        if sfound <= slast:", "                            fail(st, sat, \"SYNTAX_ERROR\", \"construct parameters in declaration order\", cat([\"out of order '\", san, \"'\"]))", "                            return stmts", "                        slast = sfound", "                        dict sp = sps[sfound]", "                        add_model_field(st, sctx[schema], sat, san, sp[type], FALSE)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        sfields.add({name: san, type: sp[type], lua: sp[lua], line: sat[line], col: sat[col]})", "                        si += 1", "                    sctx.add(\"self_seen\", TRUE)", "                    sctx.add(\"self_done\", TRUE)", "                    node = {k: \"self_init\", fields: sfields, line: e[line], col: e[col]}", "                elif tok_is(tk(st), \"op\", \"=\"):", "                    str ek = e[k]", "                    if ek == \"field\":", "                        dict fb = e[base]", "                        dict fschema = model_schema(st, e[mname])", "                        str fld = e[name]", "                        dict mctx6 = st[model_ctx]", "                        bool in_con = FALSE", "                        if NOT (mctx6 is NONE) AND mctx6[in_construct] AND fb[k] == \"var\" AND fb[name] == \"self\":", "                            if st[block_depth] == mctx6[level]:", "                                in_con = TRUE", "                        if e[model_field]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"model field '\", fld, \"' is read-only\"]))", "                            return stmts", "                        if e[is_const]:", "                            fail(st, e, \"CONST_ERROR\", \"mutable field\", cat([\"constant '\", fld, \"' is read-only\"]))", "                            return stmts", "                        dict ftypes6 = fschema[field_types]", "                        if NOT ftypes6.contains(fld):", "                            if NOT in_con OR NOT mctx6[self_done]:", "                                fail(st, e, \"NAME_ERROR\", cat([\"declared field of '\", e[mname], \"'\"]), cat([\"unknown '\", fld, \"'\"]))", "                                return stmts", "                            dict mctx6ps = mctx6[param_set]", "                            if mctx6ps.contains(fld):", "                                fail(st, e, \"REDECLARE_ERROR\", \"new field name\", cat([\"construct parameter '\", fld, \"'\"]))", "                                return stmts", "                            dict mcvar = st[vars]", "                            if mcvar.contains(fld):", "                                fail(st, e, \"REDECLARE_ERROR\", \"new field name\", cat([\"local '\", fld, \"'\"]))", "                                return stmts", "                        dict eq = advance(st)", "                        dict fexpr = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        str fexpty = fexpr[t]", "                        if ftypes6.contains(fld):", "                            if NOT assignable(fexpty, ftypes6.take(fld)):", "                                fail(st, {line: fexpr[line], col: fexpr[col]}, \"TYPE_ERROR\", cat([\"field '\", fld, \"': type \", ftypes6.take(fld)]), fexpty)", "                                return stmts", "                            node = {k: \"field_assign\", base: fb, mname: e[mname], name: fld, expr: fexpr, type: ftypes6.take(fld), line: eq[line], col: eq[col]}", "                        else:", "                            if NOT is_scalar_type(fexpty):", "                                fail(st, {line: fexpr[line], col: fexpr[col]}, \"TYPE_ERROR\", \"scalar instance field (str, flint, bool)\", fexpty)", "                                return stmts", "                            add_model_field(st, fschema, e, fld, fexpty, TRUE)", "                            if NOT (st[err] is NONE):", "                                return stmts", "                            node = {k: \"field_create\", base: fb, mname: e[mname], name: fld, expr: fexpr, type: fexpty, line: eq[line], col: eq[col]}", "                    else:", "                        if ek != \"index\" AND ek != \"dget\":", "                            fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"variable, field or index as assignment target\", ek)", "                            return stmts", "                        if ek == \"index\":", "                            dict seb = e[base]", "                            if seb[t] == \"str\":", "                                fail(st, {line: e[line], col: e[col]}, \"TYPE_ERROR\", \"mutable index target\", \"str is immutable\")", "                                return stmts", "                        dict eq2 = advance(st)", "                        dict eval2 = parse_expr(st, 0)", "                        if NOT (st[err] is NONE):", "                            return stmts", "                        node = {k: \"setindex\", target: e, expr: eval2, line: eq2[line], col: eq2[col]}", "                else:", "                    node = {k: \"exprstmt\", expr: e, line: e[line], col: e[col]}", "            if NOT decl_block:", "                stmts.add(node)", "                if NOT block_stmt:", "                    dict nx2 = tk(st)", "                    if top:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"eof\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "                    else:", "                        if nx2[type] == \"newline\":", "                            advance(st)", "                        elif nx2[type] != \"dedent\":", "                            fail(st, nx2, \"SYNTAX_ERROR\", \"end of line\", describe_tok(nx2))", "                            return stmts", "    if NOT top:", "        if tk(st)[type] == \"dedent\":", "            advance(st)", "        st.add(\"block_depth\", st[block_depth] - 1)", "    return stmts", "", "# ---------- кодогенератор ----------", "", "func wrap_flint(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func wrap_str(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_str(\", x, \")\"])", "    return x", "", "func wrap_list(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_list(\", x, \")\"])", "    return x", "", "func wrap_dict(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return x", "", "func wrap_froz(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_froz(\", x, \")\"])", "    return x", "", "func wrap_bool(str x, str ty, bool nullable) -> str:", "    if ty == \"NONE\" OR ty == \"any\" OR nullable:", "        return cat([\"krt.as_bool(\", x, \")\"])", "    return x", "", "# Приводит значение к базовому типу назначения; параметры типа проверяет рантайм.", "func as_base(str x, str target) -> str:", "    str b = base_type(target)", "    if b == \"flint\":", "        return cat([\"krt.as_flint(\", x, \")\"])", "    if b == \"str\":", "        return cat([\"krt.as_str(\", x, \")\"])", "    if b == \"bool\":", "        return cat([\"krt.as_bool(\", x, \")\"])", "    if b == \"list\":", "        return cat([\"krt.as_list(\", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.as_froz(\", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.as_dict(\", x, \")\"])", "    return cat([\"krt.as_model(\", x, lua_str(target), \")\"])", "", "# Присоединяет спецификацию параметризованного типа к коллекции.", "func typed_wrap(str x, str target) -> str:", "    if NOT is_typed_spec(target):", "        return x", "    str b = base_type(target)", "    if b == \"list\":", "        return cat([\"krt.typed_list(\", lua_str(target), \", \", x, \")\"])", "    if b == \"froz\":", "        return cat([\"krt.typed_froz(\", lua_str(target), \", \", x, \")\"])", "    if b == \"dict\":", "        return cat([\"krt.typed_dict(\", lua_str(target), \", \", x, \")\"])", "    return x", "", "func checked(str x, str ety, bool nullable, str target) -> str:", "    if ety == \"any\" AND NOT nullable:", "        return as_base(x, target)", "    return x", "", "func wrap_to(str x, str ety, bool nullable, str target) -> str:", "    if ety == \"NONE\" OR ety == \"any\" OR nullable:", "        return as_base(x, target)", "    return x", "", "func ordered_x(str x, dict e, dict other) -> str:", "    if e[t] == \"NONE\" OR e_nullable(e):", "        str ty = e[t]", "        if ty == \"NONE\":", "            ty = other[t]", "        if ty == \"str\":", "            return cat([\"krt.as_str(\", x, \")\"])", "        return cat([\"krt.as_flint(\", x, \")\"])", "    return x", "", "func emit_line(dict st, str s):", "    if NOT (st[cur_pos] is NONE):", "        dict cp = st[cur_pos]", "        if len(cp) > 0:", "            list lm = st[line_map]", "            lm.add({gen: len(st[out]) + 1, line: cp[line], col: cp[col]})", "    list o = st[out]", "    o.add(cat([spaces(st[indent] * 4), s]))", "", "func stmt_pos(dict s) -> dict:", "    str sk = s[k]", "    if sk == \"panic\":", "        return {line: s[line], col: s[col]}", "    if sk == \"decl\" OR sk == \"assign\" OR sk == \"compound\" OR sk == \"exprstmt\" OR sk == \"return\":", "        if s.contains(\"expr\"):", "            dict e = s[expr]", "            return {line: e[line], col: e[col]}", "    if sk == \"if\":", "        list brs = s[branches]", "        dict b0 = brs[0]", "        dict c0 = b0[cond]", "        return {line: c0[line], col: c0[col]}", "    if sk == \"while\":", "        dict wc = s[cond]", "        return {line: wc[line], col: wc[col]}", "    if sk == \"for\":", "        if s.contains(\"from\"):", "            dict fe = s[from]", "            return {line: fe[line], col: fe[col]}", "        dict te = s[to]", "        return {line: te[line], col: te[col]}", "    if sk == \"for_in\":", "        dict cc = s[coll]", "        return {line: cc[line], col: cc[col]}", "    return {line: s[line], col: s[col]}", "", "# Выражение -> текст Lua. Рекурсивна только сама в себя.", "func emit_expr(dict st, dict e) -> str:", "    str k = e[k]", "", "    if k == \"num\":", "        return cat([\"(\", str(e[value]), \")\"])", "    if k == \"bool\":", "        if e[value]:", "            return \"true\"", "        return \"false\"", "    if k == \"none\":", "        return \"krt.NONE\"", "    if k == \"var\":", "        return e[lua]", "", "    if k == \"model_field\":", "        return cat([\"krt.model_get(self, \", lua_str(e[name]), \")\"])", "    if k == \"field\":", "        return cat([\"krt.model_get(\", emit_expr(st, e[base]), \", \", lua_str(e[name]), \")\"])", "    if k == \"model_new\":", "        list mna = e[args]", "        list mnp = [lua_str(e[mname])]", "        flint mni = 0", "        while mni < len(mna):", "            dict mnarg = mna[mni]", "            mnp.add(emit_expr(st, mnarg))", "            mni += 1", "        return cat([\"krt.model_new(\", mnp.join(\", \"), \")\"])", "    if k == \"model_init\":", "        list mia = e[args]", "        list mip = []", "        for mia0 in mia:", "            dict mian = mia0", "            mip.add(cat([\"[\", lua_str(mian[name]), \"] = \", emit_expr(st, mian[expr])]))", "        return cat([\"krt.model_init(\", lua_str(e[mname]), \", \\{\", mip.join(\", \"), \"\\})\"])", "    if k == \"model_method\":", "        list mma2 = e[args]", "        list mmp2 = [emit_expr(st, e[base]), lua_str(e[name])]", "        list mmpt2 = e[ptypes]", "        flint mmi2 = 0", "        while mmi2 < len(mma2):", "            dict mmarg = mma2[mmi2]", "            str mmtgt = mmpt2[mmi2]", "            mmp2.add(wrap_to(emit_expr(st, mmarg), mmarg[t], e_nullable(mmarg), mmtgt))", "            mmi2 += 1", "        return cat([\"krt.model_call(\", mmp2.join(\", \"), \")\"])", "    if k == \"self_init\":", "        return \"krt.NONE\"", "", "    if k == \"func_ref\":", "        return e[lua]", "", "    if k == \"str\" OR k == \"call\":", "        list parts = e[parts]", "        list pieces = []", "        for p0 in parts:", "            dict p = p0", "            if p[kind] == \"text\":", "                pieces.add(lua_str(p[value]))", "            else:", "                dict pe = p[expr]", "                pieces.add(cat([\"krt.tostr(\", emit_expr(st, pe), \")\"]))", "        str body = \"\\\"\\\"\"", "        if len(pieces) == 1:", "            body = pieces[0]", "        elif len(pieces) > 1:", "            body = cat([\"(\", pieces.join(\" .. \"), \")\"])", "        if k == \"str\":", "            return body", "        str f = e[fn]", "        if f == \"show\":", "            return cat([\"krt.show(\", body, \")\"])", "        if f == \"show_err\":", "            return cat([\"krt.show_err(\", body, \")\"])", "        return cat([\"krt.input(\", body, \")\"])", "", "    if k == \"builtin\":", "        str bn = e[name]", "        list ba = e[args]", "        if bn == \"args\":", "            return \"krt.args()\"", "        if bn == \"time_ms\":", "            return \"krt.time_ms()\"", "        if bn == \"is_tty\":", "            return \"krt.is_tty()\"", "        dict a0 = ba[0]", "        if bn == \"len\":", "            return cat([\"krt.len(\", emit_expr(st, a0), \")\"])", "        if bn == \"type\":", "            return cat([\"krt.typeof(\", emit_expr(st, a0), \")\"])", "        if bn == \"str\":", "            return cat([\"krt.tostr(\", emit_expr(st, a0), \")\"])", "        if bn == \"flint\":", "            return cat([\"krt.to_flint(\", emit_expr(st, a0), \")\"])", "        if bn == \"up\":", "            return cat([\"krt.str_up(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"low\":", "            return cat([\"krt.str_low(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"title\":", "            return cat([\"krt.str_title(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"abs\":", "            return cat([\"krt.num_abs(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"round\":", "            return cat([\"krt.num_round(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"floor\":", "            return cat([\"krt.num_floor(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"ceil\":", "            return cat([\"krt.num_ceil(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"sqrt\":", "            return cat([\"krt.num_sqrt(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"min\" OR bn == \"max\":", "            list mvals = []", "            for mn0 in ba:", "                dict mnode = mn0", "                if base_type(mnode[t]) == \"list\":", "                    mvals.add(wrap_list(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "                else:", "                    mvals.add(wrap_flint(emit_expr(st, mnode), mnode[t], e_nullable(mnode)))", "            return cat([\"krt.num_\", bn, \"(\", mvals.join(\", \"), \")\"])", "        if bn == \"sum\":", "            return cat([\"krt.coll_sum(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"avg\":", "            return cat([\"krt.coll_avg(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"keys\":", "            return cat([\"krt.coll_keys(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"values\":", "            return cat([\"krt.coll_values(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"upk\":", "            if base_type(a0[t]) == \"dict\":", "                return cat([\"krt.coll_upk(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "            return cat([\"krt.coll_upk(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"sort\":", "            return cat([\"krt.coll_sort(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"reverse\":", "            return cat([\"krt.coll_reverse(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"clear\":", "            if base_type(a0[t]) == \"dict\":", "                return cat([\"krt.coll_clear(\", wrap_dict(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "            return cat([\"krt.coll_clear(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"map\" OR bn == \"filter\":", "            dict hf = ba[1]", "            return cat([\"krt.coll_\", bn, \"(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, hf), \")\"])", "        if bn == \"reduce\":", "            dict rf = ba[1]", "            dict rs = ba[2]", "            return cat([\"krt.coll_reduce(\", wrap_list(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", emit_expr(st, rf), \", \", emit_expr(st, rs), \")\"])", "        if bn == \"system\":", "            return cat([\"krt.system(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"assert\":", "            dict amsg = ba[1]", "            return cat([\"krt.do_assert_strict(\", emit_expr(st, a0), \", \", wrap_str(emit_expr(st, amsg), amsg[t], e_nullable(amsg)), \")\"])", "        if bn == \"expect\":", "            return cat([\"krt.expect_new(\", emit_expr(st, a0), \")\"])", "        if bn == \"read_file\":", "            return cat([\"krt.read_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"write_file\":", "            dict a1 = ba[1]", "            return cat([\"krt.write_file(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \", \", wrap_str(emit_expr(st, a1), a1[t], e_nullable(a1)), \")\"])", "        if bn == \"file_exists\":", "            return cat([\"krt.file_exists(\", wrap_str(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        if bn == \"exit\":", "            return cat([\"krt.exit(\", wrap_flint(emit_expr(st, a0), a0[t], e_nullable(a0)), \")\"])", "        return \"krt.NONE\"", "", "    if k == \"call_user\":", "        list car = e[args]", "        list cp = []", "        list cpt = e[ptypes]", "        flint ci = 0", "        while ci < len(car):", "            dict cnode = car[ci]", "            str ctgt = cpt[ci]", "            str cx = emit_expr(st, cnode)", "            cp.add(wrap_to(cx, cnode[t], e_nullable(cnode), ctgt))", "            ci += 1", "        return cat([e[lua], \"(\", cp.join(\", \"), \")\"])", "", "    if k == \"list\":", "        list its = e[items]", "        list ip = []", "        for it0 in its:", "            dict itn = it0", "            ip.add(emit_expr(st, itn))", "        return cat([\"krt.list(\\{\", ip.join(\", \"), \"\\})\"])", "", "    if k == \"dict\":", "        list prs = e[pairs]", "        str dx = \"krt.dict()\"", "        for pd0 in prs:", "            dict pd = pd0", "            dict pv = pd[value]", "            dx = cat([\"krt.dict_set(\", dx, \", \", lua_str(pd[key]), \", \", emit_expr(st, pv), \")\"])", "        return dx", "", "    if k == \"dget\":", "        dict db = e[base]", "        return cat([\"krt.dict_get(\", wrap_dict(emit_expr(st, db), db[t], e_nullable(db)), \", \", lua_str(e[key]), \")\"])", "", "    if k == \"index\":", "        dict ib = e[base]", "        dict ii = e[index]", "        str ix = wrap_flint(emit_expr(st, ii), ii[t], e_nullable(ii))", "        str ibb = base_type(ib[t])", "        if ibb == \"list\":", "            return cat([\"krt.list_index(\", wrap_list(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ibb == \"froz\":", "            return cat([\"krt.list_index(\", wrap_froz(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "        if ib[t] == \"any\":", "            return cat([\"krt.index(\", emit_expr(st, ib), \", \", ix, \")\"])", "        return cat([\"krt.str_index(\", wrap_str(emit_expr(st, ib), ib[t], e_nullable(ib)), \", \", ix, \")\"])", "", "    if k == \"slice\":", "        dict sb = e[base]", "        str sx = emit_expr(st, sb)", "        str sfn = \"str_slice\"", "        str recv = wrap_str(sx, sb[t], e_nullable(sb))", "        str sbb = base_type(sb[t])", "        if sbb == \"list\":", "            sfn = \"list_slice\"", "            recv = wrap_list(sx, sb[t], e_nullable(sb))", "        elif sbb == \"froz\":", "            sfn = \"list_slice\"", "            recv = wrap_froz(sx, sb[t], e_nullable(sb))", "        elif sb[t] == \"any\":", "            sfn = \"slice\"", "            recv = sx", "        list sp = [recv]", "        if e[from] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict fr = e[from]", "            sp.add(wrap_flint(emit_expr(st, fr), fr[t], e_nullable(fr)))", "        if e[to] is NONE:", "            sp.add(\"nil\")", "        else:", "            dict tto = e[to]", "            sp.add(wrap_flint(emit_expr(st, tto), tto[t], e_nullable(tto)))", "        if NOT (e[step] is NONE):", "            dict stp = e[step]", "            sp.add(wrap_flint(emit_expr(st, stp), stp[t], e_nullable(stp)))", "        return cat([\"krt.\", sfn, \"(\", sp.join(\", \"), \")\"])", "", "    if k == \"method\":", "        dict mb = e[base]", "        str mx = emit_expr(st, mb)", "        str mrecv = wrap_str(mx, mb[t], e_nullable(mb))", "        str mbb = base_type(mb[t])", "        if mbb == \"list\":", "            mrecv = wrap_list(mx, mb[t], e_nullable(mb))", "        elif mbb == \"froz\":", "            mrecv = wrap_froz(mx, mb[t], e_nullable(mb))", "        elif mbb == \"dict\":", "            mrecv = wrap_dict(mx, mb[t], e_nullable(mb))", "        list mar = e[args]", "        list mp = [mrecv]", "        flint mi = 0", "        while mi < len(mar):", "            dict ma = mar[mi]", "            str mspec = e[a1]", "            if mi == 1:", "                mspec = e[a2]", "            str mxx = emit_expr(st, ma)", "            if mspec == \"str\":", "                mxx = wrap_str(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"flint\":", "                mxx = wrap_flint(mxx, ma[t], e_nullable(ma))", "            elif mspec == \"dict\":", "                mxx = wrap_dict(mxx, ma[t], e_nullable(ma))", "            mp.add(mxx)", "            mi += 1", "        return cat([\"krt.\", e[rt], \"(\", mp.join(\", \"), \")\"])", "", "    if k == \"un\":", "        dict ua = e[a]", "        if e[op] == \"-\":", "            return cat([\"(-(\", wrap_flint(emit_expr(st, ua), ua[t], e_nullable(ua)), \"))\"])", "        return cat([\"(not krt.truthy_strict(\", emit_expr(st, ua), \"))\"])", "", "    if k == \"is\":", "        dict ia = e[a]", "        str ix2 = emit_expr(st, ia)", "        str ty2 = e[typename]", "        if ty2 == \"flint\":", "            return cat([\"(type(\", ix2, \") == \\\"number\\\")\"])", "        if ty2 == \"str\":", "            return cat([\"(type(\", ix2, \") == \\\"string\\\")\"])", "        if ty2 == \"bool\":", "            return cat([\"(type(\", ix2, \") == \\\"boolean\\\")\"])", "        str tyb = base_type(ty2)", "        if tyb == \"list\":", "            return cat([\"krt.is_list(\", ix2, \")\"])", "        if tyb == \"froz