     if op == \"-\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" - \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"*\":", "            return cat([\"(\", wrap_flint(xa, bna[t], e_nullable(bna)), \" * \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"/\":", "            return cat([\"krt.div(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"//\":", "            return cat([\"krt.idiv(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"%\":", "            return cat([\"krt.mod(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"**\":", "            return cat([\"krt.pow(\", wrap_flint(xa, bna[t], e_nullable(bna)), \", \", wrap_flint(xb, bnb[t], e_nullable(bnb)), \")\"])", "        if op == \"==\":", "            return cat([\"(\", xa, \" == \", xb, \")\"])", "        if op == \"!=\":", "            return cat([\"(\", xa, \" ~= \", xb, \")\"])", "        if op == \"<\" OR op == \"<=\" OR op == \">\" OR op == \">=\":", "            if bna[t] == \"any\" OR bnb[t] == \"any\":", "                str cfn = \"lt\"", "                if op == \"<=\":", "                    cfn = \"le\"", "                elif op == \">\":", "                    cfn = \"gt\"", "                elif op == \">=\":", "                    cfn = \"ge\"", "                return cat([\"krt.\", cfn, \"(\", xa, \", \", xb, \")\"])", "            return cat([\"(\", ordered_x(xa, bna, bnb), \" \", op, \" \", ordered_x(xb, bnb, bna), \")\"])", "        if op == \"AND\":", "            return cat([\"(krt.truthy_strict(\", xa, \") and krt.truthy_strict(\", xb, \"))\"])", "        if op == \"OR\":", "            return cat([\"(krt.truthy_strict(\", xa, \") or krt.truthy_strict(\", xb, \"))\"])", "        return \"krt.NONE\"", "", "    if k == \"chain\":", "        list cops = e[ops]", "        list coper = e[operands]", "        list clines = []", "        list cconds = []", "        dict cprev_node = coper[0]", "        str cprev = emit_expr(st, cprev_node)", "        flint cj = 0", "        while cj < len(cops):", "            dict co = cops[cj]", "            dict crhs_node = coper[cj + 1]", "            str crhs = \"\"", "            if cj < len(cops) - 1:", "                crhs = cat([\"__t\", str(cj + 1)])", "                clines.add(cat([\"local \", crhs, \" = \", emit_expr(st, crhs_node)]))", "            else:", "                crhs = emit_expr(st, crhs_node)", "            str cl = cprev", "            str cr = crhs", "            str cop2 = co[op]", "            if cop2 == \"==\":", "                cconds.add(cat([\"(\", cl, \" == \", cr, \")\"]))", "            elif cop2 == \"!=\":", "                cconds.add(cat([\"(\", cl, \" ~= \", cr, \")\"]))", "            elif cprev_node[t] == \"any\" OR crhs_node[t] == \"any\":", "                str cfn2 = \"lt\"", "                if cop2 == \"<=\":", "                    cfn2 = \"le\"", "                elif cop2 == \">\":", "                    cfn2 = \"gt\"", "                elif cop2 == \">=\":", "                    cfn2 = \"ge\"", "                cconds.add(cat([\"krt.\", cfn2, \"(\", cl, \", \", cr, \")\"]))", "            else:", "                if cprev_node[t] == \"NONE\" OR e_nullable(cprev_node):", "                    if cprev_node[t] == \"str\":", "                        cl = cat([\"krt.as_str(\", cl, \")\"])", "                    else:", "                        cl = cat([\"krt.as_flint(\", cl, \")\"])", "                if crhs_node[t] == \"NONE\" OR e_nullable(crhs_node):", "                    if crhs_node[t] == \"str\":", "                        cr = cat([\"krt.as_str(\", cr, \")\"])", "                    else:", "                        cr = cat([\"krt.as_flint(\", cr, \")\"])", "                cconds.add(cat([\"(\", cl, \" \", cop2, \" \", cr, \")\"]))", "            cprev = crhs", "            cprev_node = crhs_node", "            cj += 1", "        str cpre = \"\"", "        if len(clines) > 0:", "            cpre = cat([clines.join(\"; \"), \"; \"])", "        return cat([\"(function() \", cpre, \"return \", cconds.join(\" and \"), \" end)()\"])", "", "    return \"krt.NONE\"", "", "# Объявления поднимаются в начало своей функции (D11, D43).", "func collect_walk(list stmts, list out) -> list:", "    for s0 in stmts:", "        dict s = s0", "        str sk = s[k]", "        if sk == \"decl\":", "            out.add(s[lua])", "        elif sk == \"if\":", "            list brs = s[branches]", "            for b0 in brs:", "                dict b = b0", "                collect_walk(b[body], out)", "            if s.contains(\"else_body\"):", "                collect_walk(s[else_body], out)", "        elif sk == \"while\" OR sk == \"for\" OR sk == \"for_in\":", "            collect_walk(s[body], out)", "        elif sk == \"try\":", "            collect_walk(s[body], out)", "            for h0 in s[triggers]:", "                dict h = h0", "                collect_walk(h[body], out)", "            if NOT (s[any] is NONE):", "                dict ha = s[any]", "                collect_walk(ha[body], out)", "            collect_walk(s[\"finally\"], out)", "    return out", "", "func collect_scope(list stmts) -> list:", "    list out = []", "    collect_walk(stmts, out)", "    return out", "", "func emit_hoist(dict st, list names):", "    if len(names) == 0:", "        return:", "    list lua = []", "    list nones = []", "    for n0 in names:", "        str n = n0", "        lua.add(n)", "        nones.add(\"krt.NONE\")", "    emit_line(st, cat([\"local \", lua.join(\", \"), \" = \", nones.join(\", \")]))", "", "func lua_str_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = \", lua_str(d.take(k))]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func lua_true_map_keys(dict d, list ks) -> str:", "    list parts = []", "    for k in ks:", "        if d.contains(k):", "            parts.add(cat([\"[\", lua_str(k), \"] = true\"]))", "    if len(parts) == 0:", "        return \"\\{\\}\"", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "func cat_lists(list a, list b) -> list:", "    list out = []", "    for x in a:", "        out.add(x)", "    for y in b:", "        out.add(y)", "    return out", "", "func lua_str_list(list xs) -> str:", "    list parts = []", "    for x in xs:", "        parts.add(lua_str(x))", "    return cat([\"\\{\", parts.join(\", \"), \"\\}\"])", "", "# Стейтменты -> строки Lua. Рекурсивна только сама в себя.", "func emit_stmts(dict st, list stmts) -> str:", "    flint i = 0", "    while i < len(stmts):", "        dict s = stmts[i]", "        dict saved = st[cur_pos]", "        st.add(\"cur_pos\", stmt_pos(s))", "        str sk = s[k]", "        bool wrap_ret = FALSE", "        if sk == \"return\" AND i < len(stmts) - 1:", "            wrap_ret = TRUE", "            emit_line(st, \"do\")", "            st.add(\"indent\", st[indent] + 1)", "        if sk == \"model\":", "            dict msc = s[schema]", "            str mn2 = s[name]", "            dict msc_mf = msc[model_fields]", "            dict msc_ft = msc[field_types]", "            dict msc_cs = msc[consts]", "            dict msc_if = msc[init_fields]", "            dict msc_pt = msc[param_types]", "            list msc_ord = msc[order]", "            list msc_fo = msc[field_order]", "            list msc_pl = msc[params]", "            list msc_all = msc_fo", "            emit_line(st, cat([\"krt.model_define(\", lua_str(mn2), \", \", lua_str_map_keys(msc_mf, msc_ord), \", \", lua_str_map_keys(msc_ft, msc_all), \", \", lua_true_map_keys(msc_cs, msc_all), \", \", lua_true_map_keys(msc_if, msc_fo), \", \", lua_str_list(msc_pl), \", \", lua_str_map_keys(msc_pt, msc_pl), \")\"]))", "            list mflds = s[fields]", "            for mf0 in mflds:", "                dict mfn2 = mf0", "                emit_line(st, cat([\"krt.model_set_value(\", lua_str(mn2), \", \", lua_str(mfn2[name]), \", \", emit_expr(st, mfn2[expr]), \")\"]))", "            dict mcons2 = msc[ctor]", "            list mcps = mcons2[params]", "            list mcpl = [\"self\"]", "            for mcp0 in mcps:", "                dict mcp = mcp0", "                mcpl.add(mcp[lua])", "            emit_line(st, cat([\"krt.model_construct(\", lua_str(mn2), \", function(\", mcpl.join(\", \"), \")\"]))", "            st.add(\"indent\", st[indent] + 1)", "            str msv = st[current_ret]", "            st.add(\"current_ret\", \"NONE\")", "            list mcbody = mcons2[body]", "            emit_hoist(st, collect_scope(mcbody))", "            emit_stmts(st, mcbody)", "            st.add(\"current_ret\", msv)", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end)\")", "            list mmorder = msc[method_order]", "            for mmn2 in mmorder:", "                dict msmeth6 = msc[methods]", "                dict mmi2 = msmeth6.take(mmn2)", "                list mmps = [ \"self\" ]", "                list mmpl = mmi2[params]", "                for mmp0 in mmpl:", "                    dict mmp = mmp0", "                    mmps.add(mmp[lua])", "                emit_line(st, cat([\"krt.model_method(\", lua_str(mn2), \", \", lua_str(mmn2), \", function(\", mmps.join(\", \"), \")\"]))", "                st.add(\"indent\", st[indent] + 1)", "                str msv2 = st[current_ret]", "                st.add(\"current_ret\", mmi2[ret])", "                list mmbody = mmi2[body]", "                emit_hoist(st, collect_scope(mmbody))", "                emit_stmts(st, mmbody)", "                st.add(\"current_ret\", msv2)", "                bool mmend = FALSE", "                if len(mmbody) > 0:", "                    dict mmlast = mmbody[len(mmbody) - 1]", "                    if mmlast[k] == \"return\":", "                        mmend = TRUE", "                if NOT mmend:", "                    emit_line(st, \"return krt.NONE\")", "                st.add(\"indent\", st[indent] - 1)", "                emit_line(st, \"end)\")", "        elif sk == \"self_init\":", "            list sfl = s[fields]", "            for sf0 in sfl:", "                dict sf = sf0", "                emit_line(st, cat([\"krt.model_create_field(self, \", lua_str(sf[name]), \", \", sf[lua], \", \", \"false\", \", \", lua_str(sf[type]), \")\"]))", "        elif sk == \"field_create\":", "            dict fce = s[expr]", "            str fcx = checked(emit_expr(st, fce), fce[t], e_nullable(fce), s[type])", "            str fcb = emit_expr(st, s[base])", "            str fcc = \"false\"", "            if is_const_name(s[name]):", "                fcc = \"true\"", "            emit_line(st, cat([\"krt.model_create_field(\", fcb, \", \", lua_str(s[name]), \", \", fcx, \", \", fcc, \", \", lua_str(s[type]), \")\"]))", "        elif sk == \"field_assign\":", "            dict fae = s[expr]", "            str fax = checked(emit_expr(st, fae), fae[t], e_nullable(fae), s[type])", "            emit_line(st, cat([\"krt.model_set(\", emit_expr(st, s[base]), \", \", lua_str(s[name]), \", \", fax, \")\"]))", "        elif sk == \"decl\":", "            dict de = s[expr]", "            str dx = checked(emit_expr(st, de), de[t], e_nullable(de), s[type])", "            if de[t] != \"NONE\":", "                dx = typed_wrap(dx, s[type])", "            emit_line(st, cat([s[lua], \" = \", dx]))", "        elif sk == \"assign\":", "            dict ae = s[expr]", "            str ax = checked(emit_expr(st, ae), ae[t], e_nullable(ae), s[type])", "            if ae[t] != \"NONE\":", "                ax = typed_wrap(ax, s[type])", "            emit_line(st, cat([s[lua], \" = \", ax]))", "        elif sk == \"compound\":", "            dict ce = s[expr]", "            str lhs = wrap_flint(s[lua], \"flint\", s[nullable])", "            str rhs = wrap_flint(emit_expr(st, ce), ce[t], e_nullable(ce))", "            str cop = s[op]", "            str ex = \"\"", "            if cop == \"+\":", "                ex = cat([\"(\", lhs, \" + \", rhs, \")\"])", "            elif cop == \"-\":", "                ex = cat([\"(\", lhs, \" - \", rhs, \")\"])", "            elif cop == \"*\":", "                ex = cat([\"(\", lhs, \" * \", rhs, \")\"])", "            elif cop == \"/\":", "                ex = cat([\"krt.div(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"//\":", "                ex = cat([\"krt.idiv(\", lhs, \", \", rhs, \")\"])", "            elif cop == \"%\":", "                ex = cat([\"krt.mod(\", lhs, \", \", rhs, \")\"])", "            else:", "                ex = cat([\"krt.pow(\", lhs, \", \", rhs, \")\"])", "            emit_line(st, cat([s[lua], \" = \", ex]))", "        elif sk == \"setindex\":", "            dict tg = s[target]", "            dict tv = s[expr]", "            str tvx = emit_expr(st, tv)", "            if tg[k] == \"dget\":", "                dict tb = tg[base]", "                str tdx = wrap_dict(emit_expr(st, tb), tb[t], e_nullable(tb))", "                emit_line(st, cat([\"krt.dict_set(\", tdx, \", \", lua_str(tg[key]), \", \", tvx, \")\"]))", "            else:", "                dict tib = tg[base]", "                dict tii = tg[index]", "                str tbx = emit_expr(st, tib)", "                str tix = wrap_flint(emit_expr(st, tii), tii[t], e_nullable(tii))", "                str tibb = base_type(tib[t])", "                if tibb == \"list\" OR tibb == \"froz\":", "                    str tbx2 = \"\"", "                    if tibb == \"froz\":", "                        tbx2 = wrap_froz