emit_line(st, \"return krt.NONE\")", "        elif sk == \"func\":", "            list fparams = s[params]", "            list fpl = []", "            for fp0 in fparams:", "                dict fp = fp0", "                fpl.add(fp[lua])", "            emit_line(st, cat([\"local function \", s[lua], \"(\", fpl.join(\", \"), \")\"]))", "            st.add(\"indent\", st[indent] + 1)", "            str saved_ret = st[current_ret]", "            st.add(\"current_ret\", s[ret])", "            list fbody = s[body]", "            emit_hoist(st, collect_scope(fbody))", "            emit_stmts(st, fbody)", "            st.add(\"current_ret\", saved_ret)", "            bool ends_ret = FALSE", "            if len(fbody) > 0:", "                dict flast = fbody[len(fbody) - 1]", "                if flast[k] == \"return\":", "                    ends_ret = TRUE", "            if NOT ends_ret:", "                emit_line(st, \"return krt.NONE\")", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        if wrap_ret:", "            st.add(\"indent\", st[indent] - 1)", "            emit_line(st, \"end\")", "        st.add(\"cur_pos\", saved)", "        i += 1", "    return \"\"", "", "# ---------- сборка Lua ----------", "", "func generate(dict ast, dict opts) -> str:", "    dict st = {out: [], indent: 0, line_map: [], cur_pos: {}, loop_stack: [], loop_id: 0, try_id: 0, ret_id: 0, current_ret: \"NONE\", models: opts[models]}", "    emit_line(st, \"#!/usr/bin/env luajit\")", "    emit_line(st, \"-- generated by kraft\")", "    emit_line(st, cat([\"local __KRAFT_SOURCE = \", lua_str(opts[path])]))", "    emit_line(st, \"local krt = (function()\")", "    list krt_lines = split_lines(opts[krt])", "    for kl in krt_lines:", "        emit_line(st, kl)", "    emit_line(st, \"end)()\")", "", "    list src_lines = split_lines(opts[source])", "    list quoted = []", "    for sl in src_lines:", "        quoted.add(lua_str(sl))", "    emit_line(st, cat([\"krt.SOURCE_PATH = \", lua_str(opts[path])]))", "    emit_line(st, cat([\"krt.SOURCE_LINES = \\{\", quoted.join(\", \"), \"\\}\"]))", "", "    list stdin_lines = opts[stdin]", "    list quoted_stdin = []", "    for stl in stdin_lines:", "        quoted_stdin.add(lua_str(stl))", "    emit_line(st, cat([\"krt.STDIN = \\{\", quoted_stdin.join(\", \"), \"\\}\"]))", "", "    flint map_index = len(st[out]) + 1", "    emit_line(st, \"krt.LINE_MAP = \\{\\}\")", "", "    emit_line(st, \"krt.run(function()\")", "    st.add(\"indent\", 1)", "    if len(opts[prelude]) > 0:", "        list prelude_lines = split_lines(opts[prelude])", "        for pl in prelude_lines:", "            emit_line(st, pl)", "    emit_hoist(st, collect_scope(ast[stmts]))", "    emit_stmts(st, ast[stmts])", "    st.add(\"indent\", 0)", "    emit_line(st, \"end)\")", "", "    list map_parts = []", "    list lm = st[line_map]", "    for m0 in lm:", "        dict m = m0", "        map_parts.add(cat([\"[\", str(m[gen]), \"]=\\{\", str(m[line]), \",\", str(m[col]), \"\\}\"]))", "    list o = st[out]", "    o.replace(map_index - 1, cat([\"krt.LINE_MAP = \\{\", map_parts.join(\",\"), \"\\}\"]))", "    return cat([o.join(\"\\n\"), \"\\n\"])", "", "func extract_stdin(str src) -> list:", "    list out = []", "    list lines = split_lines(src)", "    for l0 in lines:", "        str line = l0", "        flint i = 0", "        flint n = len(line)", "        while i < n AND (line[i] == \" \" OR line[i] == \"\\t\"):", "            i += 1", "        if i < n AND line[i] == \"#\":", "            i += 1", "            while i < n AND (line[i] == \" \" OR line[i] == \"\\t\"):", "                i += 1", "            if line[i..i + 6] == \"stdin:\":", "                i += 6", "                while i < n AND (line[i] == \" \" OR line[i] == \"\\t\"):", "                    i += 1", "                out.add(line[i..n])", "    return out", "", "func dirname(str p) -> str:", "    flint i = len(p) - 1", "    while i >= 0:", "        if p[i] == \"/\":", "            if i == 0:", "                return \"/\"", "            return p[..i]", "        i -= 1", "    return \".\"", "", "func write_compiled(str path, str out_lua):", "    str base = path", "    if path.suff(\".kraft\"):", "        base = path[..len(path) - 6]", "    write_file(cat([base, \".lua\"]), out_lua)", "", "# ---------- CLI ----------", "", "list argv = args()", "if len(argv) >= 2 AND argv[1] == \"--version\":", "    show(xkraft 0.4.0)", "    exit(0)", "if len(argv) < 2:", "    show_err(usage: xkraft [--tokens] [-c] file.kraft)", "    exit(1)", "", "func parse_cli(list av, flint start) -> dict:", "    str m = \"run\"", "    flint i = start", "    bool scan = TRUE", "    bool use_prelude = TRUE", "    while scan AND i < len(av):", "        str cur = av[i]", "        flint step = 0", "        if cur == \"--tokens\":", "            m = \"tokens\"", "            step = 1", "        elif cur == \"-c\":", "            m = \"compile\"", "            step = 1", "        elif cur == \"--emit-lua\":", "            m = \"run\"", "            step = 1", "        elif cur == \"--no-prelude\":", "            use_prelude = FALSE", "            step = 1", "        else:", "            scan = FALSE", "        i += step", "    return {mode: m, index: i, prelude: use_prelude}", "", "dict cli = parse_cli(argv, 1)", "str mode = cli.take(\"mode\")", "flint ai = cli.take(\"index\")", "bool use_prelude = cli.take(\"prelude\")", "if ai >= len(argv):", "    show_err(usage: xkraft [--tokens] [-c] file.kraft)", "    exit(1)", "", "str path = argv[ai]", "str src = read_file(path)", "dict lx = lex(src, path)", "if NOT (lx[err] is NONE):", "    dict e = lx[err]", "    e.add(\"path\", path)", "    report_error(e, src)", "    exit(1)", "if mode == \"tokens\":", "    dump_tokens(lx[tokens])", "    exit(0)", "", "dict st = {toks: lx[tokens], pos: 0, path: path, vars: {}, nullable: {}, maybe_unset: {}, gvars: {}, gnullable: {}, gmaybe: {}, for_names